// PickKind + the pick*() wrappers, fileSizeOr0, readTextFileTail,
// sanitizeAssetName, prefHelp, inputTextProse and walkSpeedDrag now live in
// app_internal.hpp - the subsystem TUs split out of this file call them too.

// ---------------------------------------------------------------------------
// Global editor config. These are machine/muscle-memory properties (a 4K laptop
// wants a different UI scale than a 1080p desktop; navigation is personal
// preference; the emulator lives at a fixed path on this PC and the dev PS2 has
// a fixed LAN address), so they live outside the per-project .tyra - in
// editor.ini under platform::configDir(). Trivial key=value lines; the whole
// file is rewritten on any change, so load once and save the full struct.
// ---------------------------------------------------------------------------
struct EditorConfig {
    float uiScale = 0.0f;  // 0 == auto (follow the display DPI)
    NavConfig nav;
    std::string emulatorPath;  // pcsx2-qt.exe; empty = auto-detect
    std::string ps2LinkIp;     // LAN IP of a PS2 running ps2link; empty = disabled
    // Docker image the game is COMPILED in (docs/toolchain-image.md). Empty =
    // decide nothing: the generated compose file's own `${TYRAX_IMAGE:-h4570/tyra}`
    // applies, so a project's hand-written .env keeps winning exactly as before.
    // Non-empty = the Runner exports TYRAX_IMAGE for its compose commands, which
    // outranks .env. Machine config, not project data: which images this PC has
    // pulled or built is a property of the PC, and a value baked into a shared
    // .tyra would name an image a teammate does not have.
    std::string toolchainImage;
    std::string buildBackend = "native";
    // When true (default), a TYRA assertion from the running game pops up a
    // copyable error dialog. When false, errors go only to the console / Debug
    // window (the game already logs them there either way).
    bool errorPopup = true;
    // Parent folder proposed as the location for new projects. Empty = fall
    // back to ~/TyraProjects.
    std::string defaultProjectsDir;
    // Collaboration sessions: the name shown to other participants (empty =
    // the Windows user name) and where joined projects materialize (empty =
    // <editor config dir>/remote-cache).
    std::string displayName;
    std::string sessionCacheDir;
    // AI assistant backend for flow-graph generation (aigen.hpp). Machine
    // config, not project data: which CLIs/keys exist is a property of this
    // PC. The --ai-graph CLI reads the same keys (main.cpp).
    aigen::Config ai;
    // Material Editor: the preview panel's share of the window width
    // (0.25..0.75), set by dragging the splitter between the columns.
    float matEdSplit = 0.48f;
    // Credits Editor: the block list's share of the window WIDTH
    // (0.18..0.36), set by dragging the splitter beside it. Same reasoning as
    // matEdSplit - how much room a preview deserves is a property of the
    // monitor and of what you are doing, not of the project.
    float creditsSplit = 0.3f;
    // Lighting the Material / Animation Editor previews bake with: "" = the
    // scene's ambience, "*" = the neutral studio default, anything else = an
    // ambience preset name. A view preference of this machine, not project
    // data - which is also why a stale name silently falls back to the scene.
    std::string matEdLight;
    std::string animEdLight;
    // Collision-aware placement (docs/object-placement.md): inserted and
    // pasted objects rest on the surface under them instead of sinking into
    // it. A workflow preference like the navigation scheme, so it lives here
    // rather than in the .tyra.
    bool placementSnap = true;
    // The axis-view gizmo in the viewport's top-right corner. On by default;
    // it can be turned off because it sits where HUD authoring wants space.
    bool axisGizmo = true;
    // View > Comments (docs/comments.md): are all comment texts expanded?
    // Icons are always drawn; when this is off only the selected note expands.
    // A workflow preference like placementSnap, and one people stay in - the
    // session-only Preview toggles beside it in the menu are the exception.
    bool showCommentText = false;
    // Phone camera link (docs/phone-camera.md). Which port is free and how
    // much the Wi-Fi here can carry are properties of this machine, so the
    // whole thing is machine config rather than project data. The pairing code
    // persists so a paired phone keeps working across editor restarts.
    phonecam::PreviewPrefs phoneCam;
    int phoneCamPort = (int)phonecam::kDefaultPort;
    std::string phoneCamCode;      // 6 digits; generated on first use
    bool phoneCamRequireCode = true;
    // TV safe-area guides (docs/safe-areas.md) - a viewing aid like axisGizmo,
    // so it belongs to the installation, not to the project.
    bool safeAreaOn = false;
    bool safeFrame = true, safeAction = true, safeTitle = true;
    bool safeCentre = false, safeBothRegions = false;
    int safeAspect = 0;  // 0 follow project, 1 = 4:3, 2 = 16:9
    float safeOpacity = 0.55f;
    // Time machine (docs/time-machine.md): how much RAM the capture history may
    // hold. Machine-global because it is a memory budget for THIS PC, not a
    // property of the game - and it is a ceiling, not an allocation.
    int timeMachineBudgetMb = 128;
    // Interface theme (docs/editor-theme.md), stored as theme::Info::key so a
    // reordered enum cannot repaint everyone's editor. An unknown key (a
    // config written by a newer build) falls back to the default theme.
    std::string theme;
    // Viewport output mode (docs/ps2-viewport.md): false = the editor's own
    // free-aspect image, true = the scene rasterized at the GS framebuffer
    // size of the project's display mode and shown the way a TV shows it.
    // A way of looking at the scene, like the safe areas and the axis gizmo,
    // so it belongs to the installation rather than to the project.
    bool viewportPs2 = false;
    // PS2 shading in the viewport (docs/ps2-viewport.md): the console's
    // per-vertex lighting and flat-shaded triangles instead of the editor's
    // per-pixel preview. A way of looking, like viewportPs2, and independent
    // of it - triangle shading is visible at any raster.
    bool viewportPs2Shade = false;
    // GS colour simulation (docs/ps2-viewport.md): 0 = follow the project's
    // Preferences > Colour depth + dithering, 1 = force full 32-bit, 2 =
    // force 16-bit, 3 = force 16-bit + dithering. Follow-project is the
    // default so the viewport shows the truth with nothing configured.
    int viewportGsColor = 0;
    // Toolbar run target: false = the emulator (PCSX2), true = a real console
    // over ps2link. Which machine is on the desk is a property of this PC, not
    // of the game, so it lives here rather than in the .tyra.
    bool runOnPs2 = false;
    // Log panels (docs/log-panels.md): which severity levels the Output and
    // Debug windows show, as a logview level bitmask, plus their selectable-text
    // toggles. Both default to everything visible, so the split changes nothing
    // until someone hides a level - and which noise a person wants hidden is a
    // property of how they work, not of the project.
    unsigned logMaskOutput = logview::kAll;
    unsigned logMaskDebug = logview::kAll;
    bool logSelectOutput = false;
    bool logSelectDebug = false;
    // AI Assistant: may it run the tools that CHANGE things (docs/ai-chat.md)?
    // A workflow preference like placementSnap - how a person wants to work,
    // not a property of any project.
    bool chatAllowEdits = true;
    // ...and whether it may spend a Docker container and several minutes on a
    // build. Off by default: everything else the assistant does is instant and
    // one Ctrl+Z away, this is neither.
    bool chatAllowBuild = false;
    // ONE switch for every bake that can run on the GPU - the GI lightmap
    // gather and the impostor capture today (docs/editor-preferences.md,
    // Build page). Machine-global for the same reason the emulator path is:
    // whether there is a usable GPU here is a fact about the box, not about
    // any project. Each bake still falls back to the CPU on its own when the
    // GPU is missing or refuses.
    //
    // ON by default. The GI backends agree to a tolerance (2/255), not
    // bit-for-bit, so a GPU re-bake rewrites a scene's cached bytes - the
    // reason this used to be an off-by-default GI-only switch. One editor-wide
    // choice is worth more than that: whoever needs CPU-identical caches (the
    // repo's own GI examples) turns it off once. Its old key, giGpuBake, is
    // not read: it was written as 0 into every editor.ini whether or not
    // anyone chose it.
    bool gpuBakes = true;
    // Update check (docs/updates.md): whether the editor asks GitHub for a
    // newer release at startup, and one version somebody has told it to stop
    // mentioning. Which build is installed is a property of this machine, so
    // both belong here rather than in any .tyra.
    bool updateCheck = true;
    std::string updateSkipVersion;
    // The console session log (sessionlog.hpp, docs/ps2link-setup.md): lines
    // kept per session file (0 = do not write one) and session files kept in a
    // project's logs/. How much disk this machine spends on it is a property of
    // the machine.
    int consoleLogLines = 20000;
    int consoleLogFiles = 10;
    // Keep the OS title bar instead of merging it into the top bar
    // (platform.hpp, docs/editor-theme.md "Title bar"). Off = merged, where the
    // platform can (macOS, Windows). How a window looks on this desktop is a
    // property of the machine, so it lives here; read at startup only.
    bool nativeTitleBar = false;
    // Ambience Editor > Sky & time: the Detailed view instead of Simple.
    bool ambienceDetailed = false;
    // Drone Generator: the Detailed view (rail, transport, tabs) instead of Simple.
    bool droneDetailed = false;
    // Project folders opened most recently, most-recent first (the welcome
    // screen's list). Machine-global like everything else here: which projects
    // this PC has seen is a property of the PC, not of any one project.
    std::vector<std::string> recentProjects;
    // "Windows can leave the main window" (Dear ImGui multi-viewports,
    // multiviewport.hpp): a panel dragged out of the editor becomes its own OS
    // window. Off by default only in a Wayland session.
    bool multiViewports = platform::multiViewportsByDefault();
};

// How many entries the recent-projects list keeps. Ten fills the welcome
// screen without scrolling and is about as far back as "continue where I left
// off" is still useful.
static constexpr size_t kMaxRecentProjects = 10;

static std::filesystem::path editorConfigPath() {
    const std::filesystem::path base = platform::configDir();
    if (base.empty()) return {};
    return base / "editor.ini";
}

static EditorConfig loadEditorConfig() {
    EditorConfig cfg;
    const auto path = editorConfigPath();
    if (path.empty()) return cfg;
    std::ifstream f(path);
    std::string line;
    auto match = [&line](const char* key, std::string& out) {
        const std::string k = std::string(key) + "=";
        if (line.rfind(k, 0) != 0) return false;
        out = line.substr(k.size());
        return true;
    };
    std::string v;
    auto toF = [](const std::string& s, float d) { try { return std::stof(s); } catch (...) { return d; } };
    auto toI = [](const std::string& s, int d) { try { return std::stoi(s); } catch (...) { return d; } };
    auto clampScheme = [](int i) { return (i < 0 || i > 3) ? NavScheme::Default : (NavScheme)i; };
    while (std::getline(f, line)) {
        if (match("uiScale", v)) cfg.uiScale = toF(v, cfg.uiScale);
        else if (match("navScheme", v)) cfg.nav.scheme = clampScheme(toI(v, 0));
        else if (match("navMoveKeys", v)) cfg.nav.moveKeys = toI(v, 0) == 1 ? NavMoveKeys::Arrows : NavMoveKeys::WASD;
        else if (match("navOrbitSens", v)) cfg.nav.orbitSensitivity = toF(v, 1.0f);
        else if (match("navPanSens", v)) cfg.nav.panSensitivity = toF(v, 1.0f);
        else if (match("navDollySens", v)) cfg.nav.dollySensitivity = toF(v, 1.0f);
        else if (match("navZoomSens", v)) cfg.nav.zoomSensitivity = toF(v, 1.0f);
        else if (match("navInvertX", v)) cfg.nav.invertX = toI(v, 0) != 0;
        else if (match("navInvertY", v)) cfg.nav.invertY = toI(v, 0) != 0;
        else if (match("navOrbitSelection", v)) cfg.nav.orbitAroundSelection = toI(v, 1) != 0;
        else if (match("navTrackpad", v)) cfg.nav.trackpad = toI(v, cfg.nav.trackpad ? 1 : 0) != 0;
        else if (match("emulatorPath", v)) cfg.emulatorPath = v;
        else if (match("ps2LinkIp", v)) cfg.ps2LinkIp = v;
        else if (match("toolchainImage", v)) cfg.toolchainImage = v;
        else if (match("buildBackend", v))
            cfg.buildBackend = v == "docker" ? "docker" : "native";
        else if (match("errorPopup", v)) cfg.errorPopup = toI(v, 1) != 0;
        else if (match("gpuBakes", v)) cfg.gpuBakes = toI(v, 1) != 0;
        else if (match("defaultProjectsDir", v)) cfg.defaultProjectsDir = v;
        else if (match("displayName", v)) cfg.displayName = v;
        else if (match("sessionCacheDir", v)) cfg.sessionCacheDir = v;
        else if (match("aiBackend", v)) cfg.ai.backend = v;
        else if (match("aiModel", v)) cfg.ai.model = v;
        else if (match("aiThinking", v)) cfg.ai.thinking = toI(v, 0) != 0;
        else if (match("matEdSplit", v)) cfg.matEdSplit = toF(v, cfg.matEdSplit);
        else if (match("creditsSplit", v))
            cfg.creditsSplit = toF(v, cfg.creditsSplit);
        else if (match("matEdLight", v)) cfg.matEdLight = v;
        else if (match("animEdLight", v)) cfg.animEdLight = v;
        else if (match("placementSnap", v)) cfg.placementSnap = toI(v, 1) != 0;
        else if (match("axisGizmo", v)) cfg.axisGizmo = toI(v, 1) != 0;
        else if (match("showCommentText", v))
            cfg.showCommentText = toI(v, 0) != 0;
        else if (match("phoneCamPort", v)) cfg.phoneCamPort = toI(v, cfg.phoneCamPort);
        else if (match("phoneCamCode", v)) cfg.phoneCamCode = v;
        else if (match("phoneCamRequireCode", v)) cfg.phoneCamRequireCode = toI(v, 1) != 0;
        else if (match("phoneCamMaxW", v)) cfg.phoneCam.maxWidth = toI(v, cfg.phoneCam.maxWidth);
        else if (match("phoneCamMaxH", v)) cfg.phoneCam.maxHeight = toI(v, cfg.phoneCam.maxHeight);
        else if (match("phoneCamFps", v)) cfg.phoneCam.fps = toI(v, cfg.phoneCam.fps);
        else if (match("phoneCamQuality", v)) cfg.phoneCam.quality = toI(v, cfg.phoneCam.quality);
        else if (match("safeAreaOn", v)) cfg.safeAreaOn = toI(v, 0) != 0;
        else if (match("safeFrame", v)) cfg.safeFrame = toI(v, 1) != 0;
        else if (match("safeAction", v)) cfg.safeAction = toI(v, 1) != 0;
        else if (match("safeTitle", v)) cfg.safeTitle = toI(v, 1) != 0;
        else if (match("safeCentre", v)) cfg.safeCentre = toI(v, 0) != 0;
        else if (match("safeBothRegions", v)) cfg.safeBothRegions = toI(v, 0) != 0;
        else if (match("safeAspect", v)) cfg.safeAspect = toI(v, 0);
        else if (match("safeOpacity", v)) cfg.safeOpacity = toF(v, 0.55f);
        else if (match("theme", v)) cfg.theme = v;
        else if (match("viewportPs2", v)) cfg.viewportPs2 = toI(v, 0) != 0;
        else if (match("viewportPs2Shade", v))
            cfg.viewportPs2Shade = toI(v, 0) != 0;
        else if (match("viewportGsColor", v)) {
            cfg.viewportGsColor = toI(v, 0);
            if (cfg.viewportGsColor < 0 || cfg.viewportGsColor > 3)
                cfg.viewportGsColor = 0;
        }
        else if (match("runOnPs2", v)) cfg.runOnPs2 = toI(v, 0) != 0;
        else if (match("timeMachineBudgetMb", v))
            cfg.timeMachineBudgetMb = toI(v, 128);
        else if (match("phoneCamSmoothing", v))
            cfg.phoneCam.smoothing = toI(v, cfg.phoneCam.smoothing);
        // An out-of-range mask (a config written by a newer editor with more
        // levels) is clamped to the levels this build has, never to zero - an
        // empty mask would look like an empty log.
        else if (match("logMaskOutput", v))
            cfg.logMaskOutput = (unsigned)toI(v, (int)logview::kAll) & logview::kAll;
        else if (match("logMaskDebug", v))
            cfg.logMaskDebug = (unsigned)toI(v, (int)logview::kAll) & logview::kAll;
        else if (match("logSelectOutput", v)) cfg.logSelectOutput = toI(v, 0) != 0;
        else if (match("logSelectDebug", v)) cfg.logSelectDebug = toI(v, 0) != 0;
        else if (match("chatAllowEdits", v)) cfg.chatAllowEdits = toI(v, 1) != 0;
        else if (match("chatAllowBuild", v)) cfg.chatAllowBuild = toI(v, 0) != 0;
        else if (match("updateCheck", v)) cfg.updateCheck = toI(v, 1) != 0;
        else if (match("updateSkipVersion", v)) cfg.updateSkipVersion = v;
        else if (match("consoleLogLines", v))
            cfg.consoleLogLines = std::max(0, toI(v, cfg.consoleLogLines));
        else if (match("consoleLogFiles", v))
            cfg.consoleLogFiles = std::max(1, toI(v, cfg.consoleLogFiles));
        else if (match("nativeTitleBar", v)) cfg.nativeTitleBar = toI(v, 0) != 0;
        else if (match("ambienceDetailed", v)) cfg.ambienceDetailed = toI(v, 0) != 0;
        else if (match("droneDetailed", v)) cfg.droneDetailed = toI(v, 0) != 0;
        else if (match("multiViewports", v)) cfg.multiViewports = toI(v, 1) != 0;
        // One line per entry, written in list order (most recent first).
        else if (match("recentProject", v)) {
            if (!v.empty() && cfg.recentProjects.size() < kMaxRecentProjects)
                cfg.recentProjects.push_back(v);
        }
    }
    if (cfg.phoneCamPort < 1024 || cfg.phoneCamPort > 65535)
        cfg.phoneCamPort = (int)phonecam::kDefaultPort;
    if (cfg.ai.backend.empty()) cfg.ai.backend = "claude";
    return cfg;
}

static void saveEditorConfig(const EditorConfig& cfg) {
    const auto path = editorConfigPath();
    if (path.empty()) return;
    std::error_code ec;
    std::filesystem::create_directories(path.parent_path(), ec);
    std::ofstream f(path, std::ios::trunc);
    if (!f) return;
    const NavConfig& n = cfg.nav;
    f << "uiScale=" << cfg.uiScale << "\n"
      << "navScheme=" << (int)n.scheme << "\n"
      << "navMoveKeys=" << (int)n.moveKeys << "\n"
      << "navOrbitSens=" << n.orbitSensitivity << "\n"
      << "navPanSens=" << n.panSensitivity << "\n"
      << "navDollySens=" << n.dollySensitivity << "\n"
      << "navZoomSens=" << n.zoomSensitivity << "\n"
      << "navInvertX=" << (n.invertX ? 1 : 0) << "\n"
      << "navInvertY=" << (n.invertY ? 1 : 0) << "\n"
      << "navOrbitSelection=" << (n.orbitAroundSelection ? 1 : 0) << "\n"
      << "navTrackpad=" << (n.trackpad ? 1 : 0) << "\n"
      << "emulatorPath=" << cfg.emulatorPath << "\n"
      << "ps2LinkIp=" << cfg.ps2LinkIp << "\n"
      << "toolchainImage=" << cfg.toolchainImage << "\n"
      << "buildBackend=" << cfg.buildBackend << "\n"
      << "errorPopup=" << (cfg.errorPopup ? 1 : 0) << "\n"
      << "gpuBakes=" << (cfg.gpuBakes ? 1 : 0) << "\n"
      << "defaultProjectsDir=" << cfg.defaultProjectsDir << "\n"
      << "displayName=" << cfg.displayName << "\n"
      << "sessionCacheDir=" << cfg.sessionCacheDir << "\n"
      << "aiBackend=" << cfg.ai.backend << "\n"
      << "aiModel=" << cfg.ai.model << "\n"
      << "aiThinking=" << (cfg.ai.thinking ? 1 : 0) << "\n"
      << "matEdSplit=" << cfg.matEdSplit << "\n"
      << "creditsSplit=" << cfg.creditsSplit << "\n"
      << "matEdLight=" << cfg.matEdLight << "\n"
      << "animEdLight=" << cfg.animEdLight << "\n"
      << "placementSnap=" << (cfg.placementSnap ? 1 : 0) << "\n"
      << "axisGizmo=" << (cfg.axisGizmo ? 1 : 0) << "\n"
      << "showCommentText=" << (cfg.showCommentText ? 1 : 0) << "\n"
      << "phoneCamPort=" << cfg.phoneCamPort << "\n"
      << "phoneCamCode=" << cfg.phoneCamCode << "\n"
      << "phoneCamRequireCode=" << (cfg.phoneCamRequireCode ? 1 : 0) << "\n"
      << "phoneCamMaxW=" << cfg.phoneCam.maxWidth << "\n"
      << "phoneCamMaxH=" << cfg.phoneCam.maxHeight << "\n"
      << "phoneCamFps=" << cfg.phoneCam.fps << "\n"
      << "phoneCamQuality=" << cfg.phoneCam.quality << "\n"
      << "safeAreaOn=" << (cfg.safeAreaOn ? 1 : 0) << "\n"
      << "safeFrame=" << (cfg.safeFrame ? 1 : 0) << "\n"
      << "safeAction=" << (cfg.safeAction ? 1 : 0) << "\n"
      << "safeTitle=" << (cfg.safeTitle ? 1 : 0) << "\n"
      << "safeCentre=" << (cfg.safeCentre ? 1 : 0) << "\n"
      << "safeBothRegions=" << (cfg.safeBothRegions ? 1 : 0) << "\n"
      << "safeAspect=" << cfg.safeAspect << "\n"
      << "safeOpacity=" << cfg.safeOpacity << "\n"
      << "theme=" << cfg.theme << "\n"
      << "viewportPs2=" << (cfg.viewportPs2 ? 1 : 0) << "\n"
      << "viewportPs2Shade=" << (cfg.viewportPs2Shade ? 1 : 0) << "\n"
      << "viewportGsColor=" << cfg.viewportGsColor << "\n"
      << "runOnPs2=" << (cfg.runOnPs2 ? 1 : 0) << "\n"
      << "timeMachineBudgetMb=" << cfg.timeMachineBudgetMb << "\n"
      << "phoneCamSmoothing=" << cfg.phoneCam.smoothing << "\n"
      << "logMaskOutput=" << cfg.logMaskOutput << "\n"
      << "logMaskDebug=" << cfg.logMaskDebug << "\n"
      << "logSelectOutput=" << (cfg.logSelectOutput ? 1 : 0) << "\n"
      << "logSelectDebug=" << (cfg.logSelectDebug ? 1 : 0) << "\n"
      << "chatAllowEdits=" << (cfg.chatAllowEdits ? 1 : 0) << "\n"
      << "chatAllowBuild=" << (cfg.chatAllowBuild ? 1 : 0) << "\n"
      << "updateCheck=" << (cfg.updateCheck ? 1 : 0) << "\n"
      << "consoleLogLines=" << cfg.consoleLogLines << "\n"
      << "consoleLogFiles=" << cfg.consoleLogFiles << "\n"
      << "updateSkipVersion=" << cfg.updateSkipVersion << "\n"
      << "nativeTitleBar=" << (cfg.nativeTitleBar ? 1 : 0) << "\n"
      << "ambienceDetailed=" << (cfg.ambienceDetailed ? 1 : 0) << "\n"
      << "droneDetailed=" << (cfg.droneDetailed ? 1 : 0) << "\n"
      << "multiViewports=" << (cfg.multiViewports ? 1 : 0) << "\n";
    for (const std::string& dir : cfg.recentProjects) f << "recentProject=" << dir << "\n";
}

// The name a project folder shows under, and whether it is still a project at
// all: the <name>.tyra stem (project::load finds the manifest the same way),
// empty when the folder is gone or holds no manifest.
static std::string projectManifestName(const std::string& dir) {
    std::error_code ec;
    for (const auto& entry : std::filesystem::directory_iterator(dir, ec)) {
        if (entry.is_regular_file(ec) && entry.path().extension() == ".tyra")
            return entry.path().stem().string();
    }
    return "";
}

// Dedupe key for a recent-projects entry: the same folder can arrive spelled
// two ways (the Open dialog and the New Project modal disagree on slashes and
// Windows does not care about case), and the list must not grow a second row
// for a project it already has.
static std::string recentProjectKey(const std::string& dir) {
    std::string k = std::filesystem::path(dir).lexically_normal().string();
    while (!k.empty() && (k.back() == '\\' || k.back() == '/')) k.pop_back();
    for (char& c : k) c = (char)tolower((unsigned char)c);
    return k;
}

// Default parent directory proposed for new projects: the configured global
// default (Edit > Preferences) if set, else ~/TyraProjects.
static std::string defaultNewProjectLocation(const std::string& configured) {
    if (!configured.empty()) return configured;
    const std::filesystem::path home = platform::homeDir();
    return home.empty() ? std::string() : (home / "TyraProjects").string();
}

// Publish this editor's session pointer (devsession.hpp) - what a person or a
// tool needs to answer "which project is live?" without searching the disk.
// Throttled: the contents change slowly, and the point of the heartbeat is
// liveness, not resolution.
void App::publishDevSession() {
    const double now = ImGui::GetTime();
    if (now < devSessionNext_) return;
    devSessionNext_ = now + 4.0;
    devsession::Info i;
    i.pid = devsession::selfPid();
    if (!devSessionStarted_)
        devSessionStarted_ = std::chrono::duration_cast<std::chrono::seconds>(
                                 std::chrono::system_clock::now().time_since_epoch())
                                 .count();
    i.started = devSessionStarted_;
    i.heartbeat = 0;  // devsession stamps it
    if (hasProject_) {
        i.project = project_.dir;
        i.name = project_.name;
        i.scene = project_.scenes.empty() ? "" : project_.active().name;
        i.profile = project_.settings.buildProfile;
        i.liveDebug = project_.settings.liveDebug;
        i.liveLink = project_.settings.liveLink;
        // How the game is reached. The runner drops bin/ps2link.run for a
        // console deploy and removes it for an emulator build, so the marker
        // is the honest answer - and it matters: over ps2link the host file
        // server is a child of THIS editor, so closing the editor freezes
        // every devkit file mid-session.
        std::error_code ec;
        i.transport = std::filesystem::exists(
                          std::filesystem::path(project_.dir) / "bin" / "ps2link.run", ec)
                          ? "ps2link"
                          : "pcsx2";
    }
    i.gameLive = dbgState_ == DbgState::Running || dbgState_ == DbgState::Halted;
    i.gameHalted = dbgState_ == DbgState::Halted;
    i.gameFrame = dbgSnap_.frame;
    devsession::publish(i);
}

// The three bits of editor.ini the CLI needs (editorcfg.hpp). Defined here so
// the parser above stays the only one that knows the file's shape.
namespace editorcfg {
std::string configPath() { return editorConfigPath().string(); }
std::vector<std::string> recentProjects() {
    return loadEditorConfig().recentProjects;
}
std::string defaultProjectsDir() {
    return defaultNewProjectLocation(loadEditorConfig().defaultProjectsDir);
}
}  // namespace editorcfg

// WAV format inspection + in-place 16-bit conversion live in wavconvert.*.
static bool readWavFormat(const std::string& path, int& audioFormat, int& channels,
                          int& sampleRate, int& bitsPerSample) {
    return wavconvert::readFormat(path, audioFormat, channels, sampleRate,
                                  bitsPerSample);
}

// PS2 SPU2 has ~2 MB of sample RAM. Sound emitters load every sfx into it at
// scene start (audsrv ADPCM one-shots), so the whole set must fit - a sample
// too big just fails to load and plays nothing. adpenc packs 28 samples into
// 16 bytes, so ADPCM is ~2/7 of the 16-bit PCM data; that lets us estimate the
// SPU2 footprint from the WAV file size and warn before a build silently drops
// it. Budget left a little under 2 MB for audsrv's own reverb/stream buffers.
static constexpr uintmax_t kSpu2SampleBudgetBytes = 2u * 1024 * 1024;
static uintmax_t estimateAdpcmBytes(uintmax_t wavFileBytes) {
    return wavFileBytes * 2 / 7;
}

// The editor's desktop identity. It is one string on purpose: the window's
// Wayland app id, its X11 WM_CLASS, and the basename of the .desktop file and
// the icon platform::installDesktopEntry writes all have to agree, or the
// desktop cannot connect the running window to its icon.
static constexpr const char* kAppId = "tyrax-editor";

// Window/taskbar icon from the baked-in resources/icon.png.
//
// Windows needs nothing here - GLFW's Win32 backend loads the GLFW_ICON
// resource out of the .exe into the window class (resources/app.rc). On X11
// this is what puts the icon on the window; on Wayland there is no protocol
// for it at all, so GLFW reports GLFW_FEATURE_UNAVAILABLE and the icon comes
// from the desktop entry instead - checking the platform first keeps that
// expected case out of the error callback.
static void applyWindowIcon(GLFWwindow* window) {
#ifndef _WIN32
    // Cocoa has no per-window icon either (the Dock icon is the bundle's).
    if (!window || glfwGetPlatform() == GLFW_PLATFORM_WAYLAND ||
        glfwGetPlatform() == GLFW_PLATFORM_COCOA)
        return;
    int w = 0, h = 0, comp = 0;
    stbi_uc* pixels = stbi_load_from_memory(appicon::kIconPng,
                                            (int)appicon::kIconPngSize, &w, &h, &comp, 4);
    if (!pixels) return;
    const GLFWimage image{w, h, pixels};
    glfwSetWindowIcon(window, 1, &image);
    stbi_image_free(pixels);
#else
    (void)window;
#endif
}

// ---------------------------------------------------------------------------

int App::run(const std::string& initialProjectDir) {
    glfwSetErrorCallback([](int code, const char* msg) {
        std::fprintf(stderr, "GLFW error %d: %s\n", code, msg);
    });

    // The desktop entry has to exist before the window does: a Wayland
    // compositor resolves the icon by matching the surface's app id against
    // the installed .desktop files, and it looks exactly once, at map time.
    // No-op on Windows (the icon is a resource inside the .exe).
    platform::installDesktopEntry(
        kAppId, "TyraX", "Edit PS2 scenes and flow graphs, then build and run the game",
        appicon::kIconPng, appicon::kIconPngSize);

    if (!glfwInit()) return 1;

    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
    glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);
    // macOS hands out a 3.2+ core context only when it is forward-compatible;
    // without the hint glfwCreateWindow fails and the editor exits at once.
    if (glfwGetPlatform() == GLFW_PLATFORM_COCOA)
        glfwWindowHint(GLFW_OPENGL_FORWARD_COMPAT, GLFW_TRUE);
    glfwWindowHint(GLFW_SAMPLES, 4);
    glfwWindowHint(GLFW_MAXIMIZED, GLFW_TRUE);
    // What the desktop matches the window against to find the entry above -
    // the app id on Wayland, the WM_CLASS pair on X11. Both hints are accepted
    // (and ignored) by the Win32 backend, so no #ifdef is needed.
    glfwWindowHintString(GLFW_WAYLAND_APP_ID, kAppId);
    glfwWindowHintString(GLFW_X11_CLASS_NAME, kAppId);
    glfwWindowHintString(GLFW_X11_INSTANCE_NAME, kAppId);

    // Size is the restore-size when the user un-maximizes. The title carries
    // the editor version from the start: updateWindowTitle() short-circuits
    // while nothing it watches has changed, so the welcome screen would
    // otherwise keep a bare "TyraX" until the first project is opened.
    const std::string initialTitle = std::string("TyraX ") + version::kEditorVersion;
    window_ = glfwCreateWindow(1600, 900, initialTitle.c_str(), nullptr, nullptr);
    if (window_) platform::setDialogOwner(window_);
    if (!window_) {
        glfwTerminate();
        return 1;
    }
    applyWindowIcon(window_);
    // The hints stay set for every later glfwCreateWindow - including the OS
    // windows ImGui's backend makes for panels dragged out of this one, which
    // must not open maximized.
    glfwWindowHint(GLFW_MAXIMIZED, GLFW_FALSE);
    glfwMakeContextCurrent(window_);
    glfwSwapInterval(1);

    if (!glInit()) {
        std::fprintf(stderr, "Failed to load OpenGL functions\n");
        return 1;
    }

    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.ConfigFlags |= ImGuiConfigFlags_DockingEnable;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;
    // The window layout lives inside the project's .tyra file, not a global
    // imgui.ini - we load/save it via ImGui's in-memory settings API.
    io.IniFilename = nullptr;
    // The interface font: a proportional face changes every frame height the
    // style metrics are authored against, so it is loaded before the theme.
    // The theme itself is applied further down, once the ImNodes context it
    // also tints exists and the editor config has been read.
    loadUiFont();

    ImGui_ImplGlfw_InitForOpenGL(window_, true);
    ImGui_ImplOpenGL3_Init("#version 330 core");
    // Panels in their own OS windows (multiviewport.hpp). No taskbar / Dock
    // entry per panel: they are parts of this window, owned by it
    // (platform::ownToolWindow), not documents. Auto-merge stays ON
    // (ConfigViewportsNoAutoMerge false): a window dropped back over the
    // editor becomes part of it again instead of an OS window floating there.
    io.ConfigViewportsNoTaskBarIcon = true;
    io.ConfigViewportsNoAutoMerge = false;
    io.ConfigViewportsNoDefaultParent = false;  // parented to the main window
    ImNodes::CreateContext();
    // One EDITOR context per canvas. imnodes keeps panning/zoom/selection in
    // the editor context, so the Flow Graph and the Procedural graph would
    // otherwise shove each other around; and the context must never be left
    // unset - EditorContextSet(nullptr) makes the next BeginNodeEditor
    // dereference null (a startup crash when both windows are open, found the
    // hard way).
    flowEditorCtx_ = (void*)ImNodes::EditorContextCreate();
    procEditorCtx_ = (void*)ImNodes::EditorContextCreate();

    // Scale the UI for the display: the saved override if any, else auto-match
    // the monitor's content scale (a 4K laptop reports e.g. 2.0). Fonts are
    // rasterized dynamically in this ImGui, so scaling stays crisp.
    {
        const EditorConfig cfg = loadEditorConfig();
        theme_ = theme::fromKey(cfg.theme);
        uiScaleUser_ = cfg.uiScale;
        nav_ = cfg.nav;
        globalEmulatorPath_ = cfg.emulatorPath;
        globalPs2Ip_ = cfg.ps2LinkIp;
        globalToolchainImage_ = cfg.toolchainImage;
        globalBuildBackend_ = cfg.buildBackend;
        errorPopupEnabled_ = cfg.errorPopup;
        gpuBakes_ = cfg.gpuBakes;
        globalDefaultProjectsDir_ = cfg.defaultProjectsDir;
        globalDisplayName_ = cfg.displayName;
        globalSessionCacheDir_ = cfg.sessionCacheDir;
        globalAi_ = cfg.ai;
        matEdSplit_ = cfg.matEdSplit;
        creditsSplit_ = cfg.creditsSplit;
        matEdLight_ = cfg.matEdLight;
        animEdLight_ = cfg.animEdLight;
        placementSnap_ = cfg.placementSnap;
        showAxisGizmo_ = cfg.axisGizmo;
        showCommentText_ = cfg.showCommentText;
        phoneCamPrefs_ = cfg.phoneCam;
        phoneCamPort_ = cfg.phoneCamPort;
        phoneCamCode_ = cfg.phoneCamCode;
        phoneCamRequireCode_ = cfg.phoneCamRequireCode;
        showSafeArea_ = cfg.safeAreaOn;
        safeArea_.frame = cfg.safeFrame;
        safeArea_.action = cfg.safeAction;
        safeArea_.title = cfg.safeTitle;
        safeArea_.centre = cfg.safeCentre;
        safeArea_.bothRegions = cfg.safeBothRegions;
        safeArea_.aspect = cfg.safeAspect;
        safeArea_.opacity = cfg.safeOpacity;
        viewportPs2_ = cfg.viewportPs2;
        viewportPs2Shade_ = cfg.viewportPs2Shade;
        viewportGsColor_ = cfg.viewportGsColor;
        runOnPs2_ = cfg.runOnPs2;
        timeBudgetMb_ = cfg.timeMachineBudgetMb;
        logOut_.mask = cfg.logMaskOutput;
        logDbg_.mask = cfg.logMaskDebug;
        logOut_.selectText = cfg.logSelectOutput;
        logDbg_.selectText = cfg.logSelectDebug;
        chatAllowEdits_ = cfg.chatAllowEdits;
        chatAllowBuild_ = cfg.chatAllowBuild;
        globalUpdateCheck_ = cfg.updateCheck;
        globalConsoleLogLines_ = cfg.consoleLogLines;
        globalConsoleLogFiles_ = cfg.consoleLogFiles;
        globalUpdateSkip_ = cfg.updateSkipVersion;
        // The title bar is merged once, here, and stays as it is for the
        // session: un-merging a live NSWindow / HWND is not worth the edge
        // cases, so the preference says "takes effect at the next start".
        nativeTitleBar_ = cfg.nativeTitleBar;
        ambienceDetailed_ = cfg.ambienceDetailed;
        droneDetailed_ = cfg.droneDetailed;
        titleBarMerged_ = !nativeTitleBar_ && platform::mergeTitleBar(window_);
        // Before the first NewFrame (ImGui asserts on a flag that appears at
        // frame 1); later flips are applied between frames in the loop below.
        multiViewports_ = cfg.multiViewports;
        mvp::setEnabled(multiViewports_);
        // Probe the recent projects once, here: the welcome screen draws this
        // list every frame and must not scan the disk to do it.
        for (const std::string& dir : cfg.recentProjects) {
            RecentProject r;
            r.dir = dir;
            probeRecentProject(r);
            recentProjects_.push_back(r);
        }
    }
    // Colours + style metrics + the scale over them, in that order (applyTheme
    // ends in applyUiScale).
    applyTheme();

    // Drag & drop from Explorer: the dialog-free import path (PNGs land in
    // res/hud and attach to the selected menu when the Menu Editor is open).
    // Also installed on every panel's own OS window (mvp::install).
    glfwSetWindowUserPointer(window_, this);
    const GLFWdropfun onDrop = [](GLFWwindow* w, int count, const char** paths) {
        double cx = -1.0, cy = -1.0;
        glfwGetCursorPos(w, &cx, &cy);  // window coords
        if (mvp::enabled()) {           // ImGui's are desktop coords then
            int wx = 0, wy = 0;
            glfwGetWindowPos(w, &wx, &wy);
            cx += wx;
            cy += wy;
        }
        static_cast<App*>(glfwGetWindowUserPointer(w))->handleFileDrop(count, paths, (float)cx,
                                                                       (float)cy);
    };
    glfwSetDropCallback(window_, onDrop);
    mvp::install(window_, onDrop);

    if (!viewport_.init()) {
        std::fprintf(stderr, "Failed to init viewport renderer\n");
        return 1;
    }

    // Default location for new projects: the configured global default (Edit >
    // Preferences) or ~/TyraProjects. Re-proposed each time the New Project
    // modal opens, so a mid-session preference change takes effect immediately.
    std::snprintf(newLocation_, sizeof(newLocation_), "%s",
                  defaultNewProjectLocation(globalDefaultProjectsDir_).c_str());

    if (!initialProjectDir.empty()) {
        // Accept both a project directory and a <name>.tyra project file
        std::string dir = initialProjectDir;
        if (std::filesystem::path(dir).extension() == ".tyra")
            dir = std::filesystem::path(dir).parent_path().string();
        // openProjectAt is the single funnel for every local open path, and it
        // owns the format-version gate + migration prompt.
        openProjectAt(dir);  // failure leaves the welcome screen up
    }

    // Is there a newer TyraX? (docs/updates.md) A worker thread and one HTTPS
    // request, so nothing here waits on it - the answer lands in updateTick()
    // whenever it arrives, and a modal only appears if there IS something newer.
    // Never during a UI script: an unattended run must not have a dialog open
    // itself in the middle of somebody's step list.
    if (globalUpdateCheck_ && !uiScriptActive_) startUpdateCheck(false);

    // UI scripting (docs/ui-scripting.md): collect ImGui's item boxes so a
    // script can name widgets, and stop pacing to the monitor - an unattended
    // run has nobody watching, and every step costs frames.
    if (uiScriptActive_) {
        uiscript::setEnabled(true);
        glfwSwapInterval(0);
        std::printf("[ui] running %zu step(s)\n", uiScript_.size());
        std::fflush(stdout);
    }

    while (true) {
        glfwPollEvents();

        // Close request (window X or File > Exit). Guard against losing unsaved
        // edits: prompt once, and only really close after the user resolves it
        // (exitConfirmed_) or when there is nothing to lose.
        if (glfwWindowShouldClose(window_)) {
            if (exitConfirmed_ || !hasProject_ || !dirty_) break;
            glfwSetWindowShouldClose(window_, GLFW_FALSE);
            pendingAction_ = PendingAction::Exit;
            openDiscardPopup_ = true;
        }

        // Deferred from attachProject()/switchLayout(): a saved layout dump can
        // only be (re)applied between frames - existing windows get re-docked
        // here. Recipe-built layouts take the drawUI path instead.
        // The Preferences switch, applied between frames.
        if (mvp::enabled() != (multiViewports_ && mvp::supported())) mvp::setEnabled(multiViewports_);

        if (layoutLoadPending_) {
            layoutLoadPending_ = false;
            // Floating windows saved on a screen that is gone (or in their own
            // OS windows, read with the preference now off) come back into
            // the main window instead of opening out of reach.
            int wx = 0, wy = 0, ww = 0, wh = 0;
            glfwGetWindowPos(window_, &wx, &wy);
            glfwGetWindowSize(window_, &ww, &wh);
            const std::string ini = mvp::fitLayoutIni(
                (hasProject_ && !project_.windowLayouts.empty())
                    ? project_.windowLayouts[project_.activeLayout].ini
                    : std::string(),
                (float)wx, (float)wy, (float)ww, (float)wh);
            ImGui::LoadIniSettingsFromMemory(ini.c_str(), ini.size());
        }

        ImGui_ImplOpenGL3_NewFrame();
        ImGui_ImplGlfw_NewFrame();
        // Between the backend and NewFrame on purpose: the script reads the item
        // map the last frame built and queues this frame's input, and a later
        // event overrides whatever the backend just fed from a real cursor.
        uiScriptTick();
        if (uiScriptActive_) mvp::routeInjectedMouse();  // the OS window under the script's cursor
        ImGui::NewFrame();
        mvp::newFrame();

        drawUI();

        // No autosave: layout/docking changes fold into the .tyra only when
        // the user saves the project (Save / Ctrl+S). io.WantSaveIniSettings
        // is left for the next explicit saveProject() to pick up.

        publishDevSession();  // "this editor has that project open" (throttled)

        ImGui::Render();
        int w, h;
        glfwGetFramebufferSize(window_, &w, &h);
        glViewport(0, 0, w, h);
        glClearColor(0.08f, 0.08f, 0.10f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT);
        ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());

        captureFrameIfRequested(w, h);
        if (!uiShotPath_.empty()) {  // a script's shot step, after its frame drew
            captureFrameTo(uiShotPath_, w, h);
            mvp::requestPlatformShots(uiShotPath_);  // + every panel in its own OS window
            uiShotPath_.clear();
        }

        // Panels in their own OS windows: drawn and swapped here, main GL
        // context current again afterwards.
        mvp::renderPlatformWindows(window_);
        glfwSwapBuffers(window_);
    }

    // No save on exit: the user chose to discard (or had nothing unsaved).

    // Let go of the Remote Pad. Closing the editor while a button was held used
    // to leave livepad.bin saying "attached, Cross down" forever - the game's
    // staleness watchdog covers a running game, but the leftover file also reads
    // as a held button to anything inspecting it, and that made a UI-script test
    // look like it had a stuck button for 12 seconds when the hold was 4.
    if (padAttached_) {
        showRemotePad_ = false;
        remotePadTick();  // the detach path: neutral state, attached flag cleared
    }

    // Audio first: the device callback holds the LiveSynth, and a running
    // render thread writes into droneRenderResult_. Both must be done before
    // anything they touch is destroyed.
    droneAudition(false);
    // A project read still running (quit from the Opening Project screen).
    projectLoadJoin();
    droneRenderCancel_.store(true);
    if (droneRenderThread_.joinable()) droneRenderThread_.join();
    // ...and the BLSS coverage estimate, for the plainer reason that a joinable
    // std::thread destroyed at exit calls std::terminate.
    blssCovCancel_.store(true);
    if (blssCovThread_.joinable()) blssCovThread_.join();
    // The importer publishes a result into App members, which must outlive it.
    if (modelImportThread_.joinable()) modelImportThread_.join();
    // The update check writes into App members too, and its curl may be sitting
    // on a 20-second timeout - kill it rather than making the exit wait for a
    // network that is not answering.
    update::cancel();
    if (updateThread_.joinable()) updateThread_.join();

    devsession::retire(devsession::selfPid());  // stop claiming to be live
    viewport_.shutdown();
    if (vehicleEnginePreview_) vehicleEnginePreview_->stop();
    if (vehiclePreview_) vehiclePreview_->shutdown();
    if (flowEditorCtx_) ImNodes::EditorContextFree((ImNodesEditorContext*)flowEditorCtx_);
    if (procEditorCtx_) ImNodes::EditorContextFree((ImNodesEditorContext*)procEditorCtx_);
    flowEditorCtx_ = procEditorCtx_ = nullptr;
    ImNodes::DestroyContext();
    ImGui_ImplOpenGL3_Shutdown();
    ImGui_ImplGlfw_Shutdown();
    ImGui::DestroyContext();
    glfwDestroyWindow(window_);
    glfwTerminate();
    return uiScriptFailed_ ? 1 : 0;  // a UI script gates a scripted run
}

// Framebuffer self-capture, enabled by the TYRAX_SHOT environment variable
// (a directory; TYRAX_SHOT_EVERY overrides the 2-second interval). The editor
// reads back its own window and writes <dir>/shotNN.png.
//
// This exists because it is the ONLY screenshot path that works everywhere: a
// Wayland compositor may refuse external capture outright (GNOME denies the
// org.gnome.Shell.Screenshot call to unsanctioned clients, and there is no X11
// window to grab when GLFW picks the Wayland backend), and it captures what the
// editor DREW rather than what the compositor presented - which also survives
// the AMD present quirk that leaves the window blank on some machines. Used to
// verify UI work without a human at the keyboard; see the tyra-testing skill.
void App::captureFrameIfRequested(int w, int h) {
    const char* dir = getenv("TYRAX_SHOT");
    if (!dir || !*dir || w <= 0 || h <= 0) return;
    static double next = 1.0;
    static int shotNo = 0;
    static double every = 0.0;
    if (every == 0.0) {
        const char* e = getenv("TYRAX_SHOT_EVERY");
        every = e ? atof(e) : 2.0;
        if (every < 0.1) every = 0.1;
    }
    if (glfwGetTime() < next) return;
    next = glfwGetTime() + every;

    char path[512];
    std::snprintf(path, sizeof(path), "%s/shot%02d.png", dir, shotNo++);
    captureFrameTo(path, w, h);
    mvp::requestPlatformShots(path);  // + shotNN-<panel>.png per panel in its own OS window
}

// The read-back itself, also used by a UI script's `shot` step.
bool App::captureFrameTo(const std::string& path, int w, int h) {
    if (w <= 0 || h <= 0) return false;
    std::vector<unsigned char> px((size_t)w * h * 3);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);
    glReadPixels(0, 0, w, h, GL_RGB, GL_UNSIGNED_BYTE, px.data());
    // GL reads bottom-up; PNG is top-down.
    std::vector<unsigned char> flipped((size_t)w * h * 3);
    for (int y = 0; y < h; ++y)
        std::memcpy(&flipped[(size_t)y * w * 3], &px[(size_t)(h - 1 - y) * w * 3],
                    (size_t)w * 3);
    const bool ok =
        stbi_write_png(path.c_str(), w, h, 3, flipped.data(), w * 3) != 0;
    std::printf(ok ? "[shot] %s (%dx%d)\n" : "[shot] failed to write %s (%dx%d)\n",
                path.c_str(), w, h);
    std::fflush(stdout);
    return ok;
}

void App::drawUI() {
    // Project opening is staged so this cover reaches the framebuffer before
    // synchronous file parsing / viewport preparation begins. The loader must
    // stay on this thread: it replaces the custom-node/style registries.
    projectLoadTick();
    if (projectLoading_) {
        drawProjectLoadingScreen();
        return;
    }

    ImGuizmo::BeginFrame();
    // A panel alone in its dock node shows no tab strip - it draws its own
    // header (ui::PanelHeader) - and no node shows ImGui's window-menu
    // triangle. Only windows that name themselves are listed: any other
    // window keeps its tab, which is the only title it has. Must run before
    // DockSpaceOverViewport, which is where the node flags are merged.
    {
        static const char* const kSelfTitled[] = {"Project",    "Properties", "Viewport",
                                                  "Output",     "Debug",      "Flow Graph"};
        ui::PanelChromeNewFrame(kSelfTitled, IM_ARRAYSIZE(kSelfTitled));
    }
    theme::pushDockspaceColors();  // panels as cards on the ground colour
    // With no project the dock layout has nothing to show: it is kept alive
    // (KeepAliveOnly - docked windows stay docked, hidden) and the start page
    // fills the work area instead.
    ImGuiID dockspace = ImGui::DockSpaceOverViewport(
        0, ImGui::GetMainViewport(),
        ImGuiDockNodeFlags_NoWindowMenuButton |
            (hasProject_ ? 0 : ImGuiDockNodeFlags_KeepAliveOnly));
    theme::popDockspaceColors();
    if (!hasProject_) drawWelcomeScreen();

    // Terrain-layer edits (material/tint/Size/add/remove) rebuild the layer
    // passes once per frame, before the viewport renders below. Brush strokes
    // don't come through here - they rebuild only the chunks under the brush.
    if (splatPreviewDirty_ && hasProject_) {
        splatPreviewDirty_ = false;
        rebakeSplatPreview();
    }

    // Apply a pending layout rebuild now: the dockspace id exists, but no panel
    // window has been submitted yet this frame (DockBuilder must run before the
    // windows it docks are drawn). Saved-ini loads take the frame-boundary path
    // in run() instead - LoadIniSettingsFromMemory can't run mid-frame.
    if (recipeRebuildPending_) {
        recipeRebuildPending_ = false;
        buildLayoutRecipe(recipeRebuildId_, dockspace);
    }

    // First-run fallback before any project is open (no imgui.ini yet): the
    // default arrangement. Once a project attaches, applyActiveLayout() drives
    // the docking from the project's saved layouts instead.
    static bool bootLayoutDone = false;
    if (!bootLayoutDone && !hasProject_) {
        bootLayoutDone = true;
        if (ImGui::DockBuilderGetNode(dockspace) == nullptr ||
            ImGui::DockBuilderGetNode(dockspace)->IsLeafNode())
            buildLayoutRecipe((int)LayoutRecipe::Default, dockspace);
    }

    // Layouts saved before the Properties window existed: carve a slot for it
    // on the right side of the main dockspace once the Project panel has
    // settled (a signal that the loaded layout has been applied).
    if (dockPropertiesPending_) {
        if (ImGuiWindow* proj = ImGui::FindWindowByName("Project")) {
            if (proj->DockId != 0 && ImGui::DockBuilderGetNode(proj->DockId)) {
                ImGuiID center = dockspace;
                ImGuiID slot = ImGui::DockBuilderSplitNode(center, ImGuiDir_Right, 0.26f,
                                                           nullptr, &center);
                ImGui::DockBuilderDockWindow("Properties", slot);
                ImGui::DockBuilderFinish(dockspace);
            }
            dockPropertiesPending_ = false;  // Project floating -> Properties floats too
        }
    }

    // World tools open docked beside the Viewport, not floating over it.
    if (hasProject_) dockToolWindows(dockspace);

    // Is this project's game up (PCSX2 on its ELF / a ps2link deploy)? The
    // scan runs on the Runner's own thread; this only names the project.
    runner_.watchGame(hasProject_ ? &project_ : nullptr);

    // Watch the running game's log for a fresh assertion dump (throttled).
    pollGameError();

    // Stream scene edits to the running debug game (throttled; no-op unless
    // the live-patchable state changed since the last write).
    liveLinkTick();

    // Read what the running game reports about its flow graphs, and push
    // breakpoint / halt / step commands back to it (throttled).
    livedbgTick();
    livetimeTick();
    replayTick();     // what the input recorder is doing (docs/input-replay.md)
    remotePadTick();  // the editor holds the controller (docs/remote-pad.md)

    // Hot-patch edited flow graphs into the running game (throttled; writes
    // only when the compiled program actually changed).
    liveLogicTick();

    // Drain collaboration-session events (peer joins/leaves, sync completion,
    // session end) - the only place session state meets project_/ImGui.
    sessionTick();

    // Drain the phone camera link (poses, phone-side buttons, connect/drop) and
    // re-bake a running recording. Same contract as sessionTick: the only place
    // link data meets project_/ImGui.
    phoneCamTick();

    // Consume a finished AI Assistant reply: run the tool calls it asked for and
    // send their results back for the next step (docs/ai-chat.md). Same contract
    // again - the only place chat data meets project_/ImGui - and it runs whether
    // or not the window is open, so a reply is never stranded by closing it.
    aiChatTick();

    // The importer never touches ImGui/project_/viewport_ from its worker.
    // This is the one main-thread handoff point for its finished asset.
    modelImportTick();

    drawMenuBar();
    drawStatusBar();
    drawRail();
    drawCommandPalette();
    drawViewportWindow();
    drawProjectWindow();
    drawPropertiesWindow();
    drawFlowGraphWindow();
    drawOutputWindow();
    drawDebugWindow();
    drawDiscLayoutWindow();
    drawMenusWindow();
    drawMenuPreviewWindow();
    drawSaveEditorWindow();
    drawGradingWindow();
    drawAmbienceWindow();
    drawCutsceneWindow();
    drawMaterialEditorWindow();
    drawTerrainWindow();
    drawUiEditorWindow();
    drawFontManagerWindow();
    drawInputMapWindow();
    drawAssetBrowserWindow();
    drawAiChatWindow();
    drawTreeGeneratorWindow();
    drawProceduralWindow();
    drawPrefabsWindow();
    drawParticleEditorWindow();
    vehicleTick();
    vehicleDriveTick();
    drawVehicleWindow();
    drawTextureAtlasWindow();
    drawStaticBatchesWindow();
    drawWorldFactsWindow();
    drawVuProgramsWindow();
    drawDroneGeneratorWindow();
    giBakerPoll();
    shadowBakerPoll();
    modelAoPoll();
    litBakerPoll();
    blssPoll();
    drawBlssWindow();
    drawLoadingScreenWindow();
    drawCreditsWindow();
    drawAnimEditorWindow();
    drawDebuggerWindow();
    drawRemotePadWindow();
    drawSessionWindow();
    drawPhoneCamWindow();
    // The update check's answer, collected here and not from the modal's body:
    // a check started at startup has to land whether or not anything about it
    // is on screen (the giBakerPoll rule).
    updateTick();
    drawUpdateModal();
    drawNewProjectModal();
    drawPreferencesWindow();
    drawEditorPreferencesModal();
    drawAiGenerateModal();
    drawErrorModal();
    drawNavigationModal();
    drawScenePreferencesModal();
    drawNewScriptModal();
    drawNewSceneModal();
    drawDeleteSceneModal();
    drawDeleteAssetModal();
    drawModelImportModal();
    drawModelPicker();
    drawModelSizeModal();
    drawDiscardModal();
    drawLayoutModals();
    drawHostSessionModal();
    drawJoinSessionModal();
    drawSessionEndedModal();

    // Bring the freshly switched layout's headline panel to the front, now that
    // its window has been submitted this frame (docked as a background tab by
    // the recipe, or loaded from the saved ini).
    if (!pendingFocusWindow_.empty() && !layoutLoadPending_ && !recipeRebuildPending_) {
        ImGui::SetWindowFocus(pendingFocusWindow_.c_str());
        pendingFocusWindow_.clear();
    }

    // Keyboard shortcuts
    ImGuiIO& io = ImGui::GetIO();
    if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_N)) requestNewProject();
    if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_O)) requestOpenProject();
    // UI scaling (works with no project open; skip while typing in a field)
    if (!io.WantTextInput) {
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_Equal))
            setUiScale(ImClamp(uiScaleApplied_ + 0.1f, 0.5f, 4.0f));
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_Minus))
            setUiScale(ImClamp(uiScaleApplied_ - 0.1f, 0.5f, 4.0f));
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_0))
            setUiScale(0.0f);
    }
    // Run shortcuts. IsKeyChordPressed matches the modifier state exactly, so
    // plain F5 and Ctrl+F5 stay distinct: F5/F6 build && run, Ctrl+F5/Ctrl+F6
    // run the existing ELF without building.
    // Each launching chord calls openDebuggerForLaunch() first - the four here
    // are the paths that do NOT go through runSelectedTarget (they name their
    // target rather than taking the toolbar's), so this is where a launch would
    // otherwise slip past it. Ctrl+Shift+B is deliberately not among them: it
    // builds and does not run, and there is nothing to watch.
    if (hasProject_ && !runner_.busy()) {
        const bool ps2Ready = !project_.ps2LinkIp.empty();
        if (ImGui::IsKeyChordPressed(ImGuiKey_F5)) {
            openDebuggerForLaunch();
            runner_.buildAndRun(projectForBuild(), true, false, project_.activeScene);
        }
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_F5)) {
            openDebuggerForLaunch();
            runner_.runEmulatorOnly(project_, project_.activeScene);
        }
        if (ps2Ready && ImGui::IsKeyChordPressed(ImGuiKey_F6)) {
            openDebuggerForLaunch();
            runner_.buildAndRunPs2(projectForBuild(), true, false, project_.activeScene);
        }
        if (ps2Ready && ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_F6)) {
            openDebuggerForLaunch();
            runner_.buildAndRunPs2(projectForBuild(), false, false, project_.activeScene);
        }
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiMod_Shift | ImGuiKey_B))
            runner_.buildAndRun(projectForBuild(), false);
    }
    // Debugger shortcuts (docs/live-debugger.md). F9 opens the panel; the
    // transport keys only mean something while a game is reporting, and they
    // are deliberately the ones every debugger uses: F5-family for run/pause
    // is taken by "Build && Run" here, so pause/step live on F10/F11.
    if (hasProject_) {
        if (ImGui::IsKeyChordPressed(ImGuiKey_F9)) showDebugger_ = true;
        if (dbgState_ == DbgState::Running || dbgState_ == DbgState::Halted) {
            if (ImGui::IsKeyChordPressed(ImGuiKey_F10)) {
                dbgCmd_.halt = dbgState_ != DbgState::Halted;
                dbgCmd_.stepFrames = 0;
                dbgCmd_.stepUntilFire = false;
                dbgCmdWritten_ = false;
                dbgScrub_ = -1;
            }
            if (ImGui::IsKeyChordPressed(ImGuiKey_F11)) {
                dbgCmd_.halt = false;
                dbgCmd_.stepFrames = 1;
                dbgCmd_.stepUntilFire = false;
                dbgCmdWritten_ = false;
                dbgScrub_ = -1;
            }
        }
    }
    if (hasProject_) {
        // Ctrl+S is host-only in a joined session (the client's disk copy is
        // the sync cache; the host owns persistence).
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_S) &&
            session_.role() != session::Session::Role::Client)
            saveAll("Saved");
        if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_Comma))
            openProjectPreferences();
        if (!io.WantTextInput) {
            // While the Material Editor has focus, Ctrl+Z drives ITS undo
            // stack (paint strokes + material edits, saved straight to disk) -
            // undoing scene changes from under an open material would be
            // surprising. Same focus-scoping as the Flow Graph's Ctrl+C/V.
            if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_Z)) {
                if (matEdFocused_) matEdUndoLast();
                else undo();
            }
            if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_Y) &&
                !matEdFocused_)
                redo();
            // While the Flow Graph window has focus, Ctrl+C/V act on its nodes
            // (handled in drawFlowGraphWindow); otherwise they copy scene objects.
            if (!flowGraphFocused_) {
                if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiMod_Shift | ImGuiKey_G)) ungroupSelection();
                else if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_G)) groupSelection();
                if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_C)) copyObject();
                if (ImGui::IsKeyChordPressed(ImGuiMod_Ctrl | ImGuiKey_V)) pasteObject();
            }
        }
    }
}

void App::applyUiScale() {
    float monitor = window_ ? ImGui_ImplGlfw_GetContentScaleForWindow(window_) : 1.0f;
    if (monitor <= 0.0f) monitor = 1.0f;
    float scale = uiScaleUser_ > 0.0f ? uiScaleUser_ : monitor;
    scale = ImClamp(scale, 0.5f, 4.0f);  // keep the UI usable whatever we read

    ImGuiStyle& style = ImGui::GetStyle();
    style = baseStyle_;           // reset to the unscaled reference...
    style.ScaleAllSizes(scale);   // ...then scale spacing/padding/borders
    style.FontScaleMain = scale;  // dynamic fonts re-rasterize at the new size
    // ImGuiStyle's constructor leaves FontSizeBase at 0 ("ask the font atlas on
    // the first frame"), and baseStyle_ carries that zero - so restore the size
    // loadUiFont() picked. Left at 0 when no system face resolved, which is
    // exactly what makes ImGui fall back to the built-in font's own size.
    style.FontSizeBase = uiFontSize_;
    if (uiScaleApplied_ != scale) {
        // The Flow Graph canvas lays its nodes out in scaled grid space (see
        // drawFlowGraphWindow), so the positions it pushed into imnodes belong
        // to the old scale - re-push them or the graph draws at the new node
        // size with the old spacing.
        flowPositionsApplied_ = false;
    }
    uiScaleApplied_ = scale;
}

// Writes the whole global editor config (editor.ini) from the App members.
// All save sites funnel through here so no field is dropped - a bare
// {uiScaleUser_, nav_} would wipe the emulator path / PS2 IP on the next
// UI-scale or navigation change.
void App::saveGlobalConfig() {
    std::vector<std::string> recent;
    recent.reserve(recentProjects_.size());
    for (const RecentProject& r : recentProjects_) recent.push_back(r.dir);
    saveEditorConfig({uiScaleUser_, nav_, globalEmulatorPath_, globalPs2Ip_,
                      globalToolchainImage_, globalBuildBackend_,
                      errorPopupEnabled_, globalDefaultProjectsDir_,
                      globalDisplayName_, globalSessionCacheDir_, globalAi_,
                      matEdSplit_, creditsSplit_, matEdLight_, animEdLight_,
                      placementSnap_, showAxisGizmo_, showCommentText_,
                      phoneCamPrefs_, phoneCamPort_, phoneCamCode_,
                      phoneCamRequireCode_, showSafeArea_, safeArea_.frame,
                      safeArea_.action, safeArea_.title, safeArea_.centre,
                      safeArea_.bothRegions, safeArea_.aspect,
                      safeArea_.opacity, timeBudgetMb_,
                      theme::info(theme_).key, viewportPs2_,
                      viewportPs2Shade_, viewportGsColor_, runOnPs2_,
                      logOut_.mask, logDbg_.mask, logOut_.selectText,
                      logDbg_.selectText, chatAllowEdits_, chatAllowBuild_,
                      gpuBakes_, globalUpdateCheck_, globalUpdateSkip_,
                      globalConsoleLogLines_, globalConsoleLogFiles_,
                      nativeTitleBar_, ambienceDetailed_, droneDetailed_,
                      std::move(recent), multiViewports_});
}

void App::setUiScale(float userScale) {
    uiScaleUser_ = userScale;  // 0 == auto (follow the display DPI)
    applyUiScale();
    saveGlobalConfig();
}

// The interface font (docs/editor-theme.md). ImGui's built-in bitmap face is
// the loudest "this is a debug overlay" signal the editor gives off, so the
// first system UI font this machine has is loaded over it. Called once, before
// the first frame; fonts are rasterized dynamically in this ImGui, so the UI
// scale re-bakes the glyphs on its own and there is no atlas to rebuild here.
void App::loadUiFont() {
    // 15 px against ProggyClean's 13: a proportional face needs the extra pixel
    // to read as well at the same nominal size, and the whole UI is authored in
    // scaled() multiples of it rather than in absolute rows.
    constexpr float kUiFontSize = 15.0f;
    ImFontAtlas* atlas = ImGui::GetIO().Fonts;

    // The editor's own typeface, embedded (resources/fonts, SIL OFL 1.1):
    // Geist, Geist SemiBold for headings, Geist Mono for numbers and logs. The
    // same letters on every platform, whatever the machine has installed.
    // The atlas only borrows the bytes (they live in the executable).
    auto embedded = [&](const unsigned char* data, std::size_t size) {
        ImFontConfig cfg;
        cfg.FontDataOwnedByAtlas = false;
        return atlas->AddFontFromMemoryTTF(const_cast<unsigned char*>(data), (int)size,
                                           kUiFontSize, &cfg);
    };
    // Each embedded face gets a system face MERGED behind it: ImGui looks a
    // glyph up in the merged sources in order, so anything Geist does not draw
    // (the macOS Command sign, arrows, CJK in a project name...) still comes
    // out in a face that has it, instead of a missing-glyph box.
    auto fallback = [&](const std::string& path, int faceNo) {
        if (path.empty()) return;
        ImFontConfig cfg;
        cfg.MergeMode = true;
        cfg.FontNo = faceNo;
        atlas->AddFontFromFileTTF(path.c_str(), kUiFontSize, &cfg);
    };
    std::string sysRegular, sysBold, sysMono;
    int sysBoldFace = 0;
    for (const platform::UiFontFamily& f : platform::uiFontFiles()) {
        sysRegular = platform::systemFontPath(f.file);
        if (sysRegular.empty()) continue;
        sysBold = platform::systemFontPath(f.boldFile);
        sysBoldFace = f.boldFace;
        break;
    }
    for (const platform::SystemFont& f : platform::monoFontFiles()) {
        sysMono = platform::systemFontPath(f.file);
        if (!sysMono.empty()) break;
    }

    if (embedded(uifonts::kGeistRegular, uifonts::kGeistRegularSize)) {
        fallback(sysRegular, 0);
        uiFontSize_ = kUiFontSize;
        uiFontLabel_ = "Geist";
    }
    if (ImFont* bold = embedded(uifonts::kGeistSemiBold, uifonts::kGeistSemiBoldSize)) {
        fallback(sysBold.empty() ? sysRegular : sysBold, sysBold.empty() ? 0 : sysBoldFace);
        ui::setBoldFont(bold);
    }
    if (ImFont* mono = embedded(uifonts::kGeistMonoRegular, uifonts::kGeistMonoRegularSize)) {
        fallback(sysMono, 0);
        ui::setMonoFont(mono);
        monoFontLabel_ = "Geist Mono";
    }
    if (uiFontSize_ > 0.0f) return;
    // The embedded face failed to load (it should not): the built-in font
    // stays, and uiFontSize_ 0 leaves FontSizeBase alone so ImGui keeps that
    // font's own size.
    std::printf("[ui] embedded interface font failed to load - using the built-in font\n");
}

// Colours + metrics + the DPI scale over them. One function because baseStyle_
// IS the themed style: the scale path resets to it every time, so a theme that
// only wrote ImGui::GetStyle() would be undone by the next zoom step.
unsigned int App::appIconTexture() {
    if (appIconTried_) return appIconTex_;
    appIconTried_ = true;
    int w = 0, h = 0, comp = 0;
    stbi_uc* px = stbi_load_from_memory(appicon::kIconPng, (int)appicon::kIconPngSize, &w, &h, &comp, 4);
    if (!px) return 0;
    glGenTextures(1, &appIconTex_);
    glBindTexture(GL_TEXTURE_2D, appIconTex_);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glUploadTexRgba(w, h, px);  // the one-call upload crashes AMD (skill rule)
    stbi_image_free(px);
    return appIconTex_;
}

void App::applyTheme() {
    ImGuiStyle themed;  // fresh ImGui defaults for everything the theme leaves
    theme::apply(theme_, themed);
    baseStyle_ = themed;
    theme::applyImNodes();  // the two node canvases follow the palette
    applyUiScale();
}

void App::setTheme(theme::Id id) {
    theme_ = id;
    applyTheme();
    saveGlobalConfig();
}

void App::drawMenuBar() {
    // A taller bar than one row of menus: ImGui sizes the main menu bar - and
    // the baseline its contents sit on - from FramePadding at Begin time, so
    // the larger padding is pushed for BeginMainMenuBar alone. Everything drawn
    // inside (the logo menu, its popups, the toolbar) is back on the normal
    // metrics; the toolbar centres its controls on the taller bar itself.
    ImGui::PushStyleVar(ImGuiStyleVar_FramePadding,
                        ImVec2(ImGui::GetStyle().FramePadding.x, scaled(12.0f)));
    const bool barOpen = ImGui::BeginMainMenuBar();
    ImGui::PopStyleVar();
    if (barOpen) {
        // Merged title bar: the OS's strip at the left end (macOS traffic
        // lights) stays free - everything below starts after it.
        if (const float inset = titleBarInsetLeft(); inset > 0.0f) {
            ImGui::Dummy(ImVec2(ImMax(0.0f, ImGui::GetWindowPos().x + inset -
                                                 ImGui::GetCursorScreenPos().x),
                                1.0f));
            ImGui::SameLine(0.0f, 0.0f);
        }
        drawLogoMenu();  // the mark + wordmark: the button the ten menus live behind
        drawToolbar();   // shell_ui.cpp; the status message is in the status bar
        // Merged title bar: Windows caption buttons + where the bar may drag
        // the window (shell_ui.cpp). Last, so every widget above is known.
        drawTitleBarControls();
        ImGui::EndMainMenuBar();
    }
}

// The editor's ten menus (File ... Help), drawn as submenus of the logo menu's
// popup (drawLogoMenu). Each is an ordinary BeginMenu, exactly what used to sit
// on the bar itself - a popup of BeginMenus is a menu of submenus to ImGui -
// so the labels, the items and their shortcuts did not change.
void App::drawMainMenus() {
    if (menuact::BeginMenu("File")) {
        if (menuact::MenuItem("New Project...", "Ctrl+N")) requestNewProject();
        if (menuact::MenuItem("Open Project...", "Ctrl+O")) requestOpenProject();
        drawRecentProjectsMenu();
        ImGui::Separator();
        const bool sessionClient =
            session_.role() == session::Session::Role::Client;
        if (menuact::MenuItem("Save", "Ctrl+S", false, hasProject_ && !sessionClient))
            saveAll("Saved");
        if (sessionClient && ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "You joined this project as a session participant -\n"
                "the HOST owns saving and committing. Leave the session\n"
                "to keep your local copy and save it yourself.");
        // No keyboard shortcut on purpose: Ctrl+W is one slip away from the
        // W that flies the viewport camera, and this throws the project out
        // of the editor.
        if (menuact::MenuItem("Close Project", nullptr, false, hasProject_))
            requestCloseProject();
        ImGui::Separator();
        if (menuact::MenuItem("Exit")) requestExit();
        menuact::EndMenu();
    }
    // Edit stays enabled without a project so the machine-global editor
    // settings (emulator path, PS2 IP) can be set before creating one; the
    // project-scoped items below disable themselves on their own state.
    if (menuact::BeginMenu("Edit")) {
        const bool objectSelected =
            hasProject_ && selectedObject_ >= 0 &&
            selectedObject_ < (int)project_.objects().size();
        if (menuact::MenuItem("Undo", "Ctrl+Z", false, history_.canUndo())) undo();
        if (menuact::MenuItem("Redo", "Ctrl+Y", false, history_.canRedo())) redo();
        ImGui::Separator();
        const char* copyLabel =
            selection_.size() > 1 ? "Copy objects" : "Copy object";
        // A pending paste is still following the cursor - the same command
        // settles it (see pasteObject).
        const char* pasteLabel = pastePending_ ? "Place paste"
                                 : clipboard_.size() > 1 ? "Paste objects"
                                                         : "Paste object";
        if (menuact::MenuItem("Group objects", "Ctrl+G", false, selection_.size() > 1 && selectedGroup().empty())) groupSelection();
        if (menuact::MenuItem("Ungroup objects", "Ctrl+Shift+G", false, objectSelected)) ungroupSelection();
        if (menuact::MenuItem(copyLabel, "Ctrl+C", false, objectSelected)) copyObject();
        if (menuact::MenuItem(pasteLabel, "Ctrl+V", false,
                            hasProject_ && (pastePending_ || !clipboard_.empty())))
            pasteObject();
        ImGui::Separator();
        // The modal seeds its own fields when it opens (the start page opens
        // it too).
        if (menuact::MenuItem("Preferences...")) {
            openEditorPrefsPopup_ = true;
        }
        menuact::EndMenu();
    }
    if (menuact::BeginMenu("View")) {
        ImGui::TextDisabled("Interface scale");
        if (menuact::MenuItem("Zoom in", "Ctrl+="))
            setUiScale(ImClamp(uiScaleApplied_ + 0.1f, 0.5f, 4.0f));
        if (menuact::MenuItem("Zoom out", "Ctrl+-"))
            setUiScale(ImClamp(uiScaleApplied_ - 0.1f, 0.5f, 4.0f));
        if (menuact::MenuItem("Auto (match display DPI)", "Ctrl+0", uiScaleUser_ == 0.0f))
            setUiScale(0.0f);
        ImGui::Separator();
        const float presets[] = {1.0f, 1.25f, 1.5f, 1.75f, 2.0f, 2.5f, 3.0f};
        for (float v : presets) {
            char label[16];
            std::snprintf(label, sizeof(label), "%d%%", (int)std::lround(v * 100.0f));
            if (menuact::MenuItem(label, nullptr, std::abs(uiScaleApplied_ - v) < 0.001f))
                setUiScale(v);
        }
        ImGui::Separator();
        ImGui::TextDisabled("Current: %d%%%s", (int)std::lround(uiScaleApplied_ * 100.0f),
                            uiScaleUser_ == 0.0f ? " (auto)" : "");
        ImGui::Separator();
        // The one navigation setting worth reaching without opening a
        // modal: it changes what a click DOES to the camera, so it gets
        // toggled far more often than sensitivities are tuned. Same field
        // the Navigation controls popup edits - one setting, two doors.
        if (menuact::MenuItem("Orbit around selected object", nullptr,
                            nav_.orbitAroundSelection)) {
            nav_.orbitAroundSelection = !nav_.orbitAroundSelection;
            saveGlobalConfig();
            navFocusedIndex_ = -1;  // re-snap next frame if something is selected
        }
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Selecting an object moves the camera pivot onto it, so a\n"
                "right-drag orbits around that object instead of the terrain\n"
                "centre. Pan, zoom and the forward drag still move freely.");
        if (menuact::MenuItem("Navigation controls...")) openNavigationPopup_ = true;

        // Theme next to the interface scale: both are "how the editor
        // looks on THIS machine", both live in editor.ini, and a picker
        // buried in Preferences is one nobody finds. Also in
        // Edit > Preferences > Appearance.
        if (menuact::BeginMenu("Theme")) {
            for (int i = 0; i < (int)theme::Id::Count; ++i) {
                const theme::Info& ti = theme::info((theme::Id)i);
                if (menuact::MenuItem(ti.label, nullptr, theme_ == (theme::Id)i))
                    setTheme((theme::Id)i);
                if (ImGui::IsItemHovered()) ImGui::SetTooltip("%s", ti.desc);
            }
            menuact::EndMenu();
        }

        ImGui::Separator();
        ImGui::TextDisabled("Viewport output");
        {
            // Two ways of looking at the same scene: the editor's own
            // image, which fills whatever shape the viewport is docked to,
            // or the console's - rasterized at the GS framebuffer size of
            // the project's display mode and fitted into the TV's picture.
            struct OutItem {
                bool ps2;
                const char* label;
                const char* help;
            };
            static const OutItem outs[] = {
                {false, "Editor",
                 "The viewport's own image: full resolution, and as wide as\n"
                 "you docked the panel."},
                {true, "PS2 output (GS)",
                 "What the console draws: the scene rasterized at the GS\n"
                 "framebuffer size of Preferences > Picture mode, then\n"
                 "fitted into the 4:3 / 16:9 picture a TV shows. Pixels are\n"
                 "the console's, and so is the framing."},
            };
            for (const OutItem& it : outs) {
                if (menuact::MenuItem(it.label, nullptr, viewportPs2_ == it.ps2,
                                    hasProject_) &&
                    viewportPs2_ != it.ps2) {
                    viewportPs2_ = it.ps2;
                    saveGlobalConfig();
                }
                if (ImGui::IsItemHovered()) ImGui::SetTooltip("%s", it.help);
            }
            if (viewportPs2_ && hasProject_) {
                const Viewport::Ps2Output o = ps2ViewportOutput();
                ImGui::TextDisabled("  %dx%d, %s", o.bufW, o.bufH,
                                    project_.settings.widescreen ? "16:9" : "4:3");
            }
            // The two look simulations compose with either output mode:
            // triangle shading and 16-bit banding are visible (and true)
            // at any raster.
            if (menuact::MenuItem("PS2 shading", nullptr, viewportPs2Shade_,
                                hasProject_)) {
                viewportPs2Shade_ = !viewportPs2Shade_;
                saveGlobalConfig();
            }
            if (ImGui::IsItemHovered())
                ImGui::SetTooltip(
                    "Shade the way the console does: lights, occlusion and\n"
                    "fog per VERTEX, most surfaces flat-shaded - one colour\n"
                    "per triangle. Off = the editor's smooth per-pixel look.");
            if (menuact::BeginMenu("GS colour", hasProject_)) {
                static const char* kGsColorNames[] = {
                    "Match project", "Full 32-bit", "16-bit",
                    "16-bit + dithering"};
                for (int i = 0; i < 4; ++i) {
                    if (menuact::MenuItem(kGsColorNames[i], nullptr,
                                        viewportGsColor_ == i) &&
                        viewportGsColor_ != i) {
                        viewportGsColor_ = i;
                        saveGlobalConfig();
                    }
                }
                menuact::EndMenu();
            }
            if (ImGui::IsItemHovered())
                ImGui::SetTooltip(
                    "The framebuffer depth the picture is shown at. Match\n"
                    "project follows Preferences > Colour depth (and its\n"
                    "dithering); the forced modes answer \"what if\" without\n"
                    "touching the project.");
        }

        ImGui::Separator();
        ImGui::TextDisabled("Render mode");
        const char* modeNames[] = {"Solid", "Wireframe", "Wire + Solid"};
        // Switching costs no write and no dirty flag: the render mode is
        // VIEW state, not content, and saveProject() reads it off the
        // viewport at save time - exactly like the projection below. This
        // used to call saveAll(), which silently committed every pending
        // scene edit and cleared the save icon along the way.
        for (int i = 0; i < 3; ++i) {
            const bool active = (int)viewport_.viewMode() == i;
            if (menuact::MenuItem(modeNames[i], nullptr, active, hasProject_) && !active)
                viewport_.setViewMode((Viewport::ViewMode)i);
        }

        ImGui::Separator();
        ImGui::TextDisabled("Projection");
        {
            // Perspective + the parallel views. The axis entries also aim
            // the camera down that world axis; orbiting afterwards drops
            // the lock and returns to whichever free mode was in use
            // before the axis view was picked.
            struct ProjItem {
                Viewport::Projection p;
                const char* label;
                const char* shortcut;
            };
            static const ProjItem items[] = {
                {Viewport::Projection::Perspective, "Perspective", "Num 5"},
                {Viewport::Projection::Ortho, "Orthographic", "Num 5"},
                {Viewport::Projection::OrthoTop, "Top (-Y)", "Num 7"},
                {Viewport::Projection::OrthoBottom, "Bottom (+Y)", "Ctrl+Num 7"},
                {Viewport::Projection::OrthoFront, "Front (-Z)", "Num 1"},
                {Viewport::Projection::OrthoBack, "Back (+Z)", "Ctrl+Num 1"},
                {Viewport::Projection::OrthoRight, "Right (-X)", "Num 3"},
                {Viewport::Projection::OrthoLeft, "Left (+X)", "Ctrl+Num 3"},
            };
            for (const ProjItem& it : items) {
                const bool active = viewport_.projection() == it.p;
                if (menuact::MenuItem(it.label, it.shortcut, active, hasProject_) &&
                    !active)
                    setViewProjection(it.p);
            }
            if (menuact::MenuItem("Axis gizmo", nullptr, showAxisGizmo_)) {
                showAxisGizmo_ = !showAxisGizmo_;
                saveGlobalConfig();
            }
            if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
                ImGui::SetTooltip(
                    "The axis widget in the viewport's top-right corner:\n"
                    "click an axis ball to snap to that orthographic view,\n"
                    "click the hub to switch perspective/parallel.");
        }

        ImGui::Separator();
        ImGui::TextDisabled("Placement");
        if (menuact::MenuItem("Snap to surface", nullptr, placementSnap_)) {
            placementSnap_ = !placementSnap_;
            saveGlobalConfig();
        }
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Inserted and pasted objects rest on the surface under "
                "them\n(the terrain, or the top of the object below) "
                "instead of\nsinking into it. A machine setting, not "
                "project data.");

        ImGui::Separator();
        ImGui::TextDisabled("Preview");
        // Editor notes (docs/comments.md). Icons are always present; this
        // persisted option expands every note instead of only the selected
        // one.
        if (menuact::MenuItem("Comments", nullptr, showCommentText_, hasProject_)) {
            showCommentText_ = !showCommentText_;
            saveGlobalConfig();
        }
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Expand every comment's text in the viewport. When off,\n"
                "the message icons stay visible and clickable, but only\n"
                "the selected comment shows its text. Off by default.\n"
                "Notes are editor-only either way: nothing reaches the game.");
        if (menuact::MenuItem("Distance fog", nullptr, showFog_, hasProject_)) {
            showFog_ = !showFog_;
            applyProjectToViewport();  // suppress/restore fog in the viewport now
        }
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip("Preview the scene's distance fog in the editor. "
                              "Turn off to see distant geometry - does not "
                              "affect the generated game.");
        if (menuact::MenuItem("Nav mesh overlay", nullptr, showNavOverlay_,
                            hasProject_))
            showNavOverlay_ = !showNavOverlay_;
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Show the baked navigation grid the AI flow nodes walk on "
                "(green = walkable). Tune it in Project > Preferences > "
                "AI navigation.");
        if (menuact::MenuItem("Collision boxes", nullptr, showCollisionBoxes_,
                            hasProject_))
            showCollisionBoxes_ = !showCollisionBoxes_;
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Draw the box the GAME blocks the player and the "
                "third-person\ncamera with (red). A model collides as its "
                "bounding box, not its\nmesh, so this is what explains a "
                "prop you cannot walk up to or a\ncamera that pulls in "
                "early. The running game can draw the same\nboxes - "
                "Preferences > Build & debug > Show collision boxes.");
        if (menuact::MenuItem("Static batches", nullptr, showBatchOverlay_,
                            hasProject_)) {
            showBatchOverlay_ = !showBatchOverlay_;
            batchDirty_ = true;
        }
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Colour every static object by the batch it merges into, "
                "with\nsolo objects in grey, and draw each batch's MERGED "
                "BOX. That box\nis what the frustum and the draw-distance "
                "test are applied to -\na batch draws as a unit - so an "
                "over-wide one is geometry the\nunbatched scene would "
                "cull. Tools > Static Batches lists them.");
        if (menuact::MenuItem("Procedural preview", nullptr, showProcPreview_,
                            hasProject_))
            showProcPreview_ = !showProcPreview_;
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Draw what the procedural volumes generate. Turn it off to "
                "work on\nwhat is underneath - a finished forest hides the "
                "ground it grows on.\nThe graph keeps being evaluated, so "
                "the budget readout and the seed\nsimulator stay live; only "
                "the geometry goes.");
        if (menuact::MenuItem("Scroller preview", nullptr, showScrollerPreview_,
                            hasProject_))
            showScrollerPreview_ = !showScrollerPreview_;
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Draw the sliding ghost copies of EVERY endless scroller's\n"
                "segments. Turn it off to work on the member objects the\n"
                "copies are made of - a running belt fills its whole window\n"
                "with them. One belt at a time is 'Show belt preview' in\n"
                "that scroller's Properties. The belt markers stay either\n"
                "way, and the clone count and warnings stay live.");

        ImGui::Separator();
        ImGui::TextDisabled("TV safe frame");
        if (menuact::MenuItem("PAL 4:3 frame", nullptr, showPal_)) showPal_ = !showPal_;
        if (menuact::MenuItem("NTSC frame", nullptr, showNtsc_)) showNtsc_ = !showNtsc_;

        menuact::EndMenu();
    }
    if (menuact::BeginMenu("Layout", hasProject_)) {
        drawLayoutMenu();
        menuact::EndMenu();
    }
    if (menuact::BeginMenu("Scene", hasProject_)) {
        if (menuact::BeginMenu("Add")) {
            drawAddObjectMenu();
            menuact::EndMenu();
        }
        ImGui::Separator();
        if (menuact::MenuItem("Drop to floor", "End", false, !selection_.empty()))
            dropSelectionToFloor();
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Rest every selected object on the first surface below it "
                "-\nthe terrain or the top of another object.");
        ImGui::Separator();
        if (menuact::MenuItem("Scene Preferences...")) openScenePreferences();
        menuact::EndMenu();
    }
    if (menuact::BeginMenu("Project", hasProject_)) {
        const bool busy = runner_.busy();
        if (menuact::MenuItem("Preferences...", "Ctrl+,"))
            openProjectPreferences();
        ImGui::Separator();
        if (menuact::MenuItem("Export PS2 ISO", nullptr, false, !busy))
            runner_.exportIso(projectForBuild());
        if (menuact::MenuItem("Disc Layout...")) {
            showDiscLayout_ = true;
            discPlanDirty_ = true;
        }
        menuact::EndMenu();
    }
    // VS-style top-level Build menu (the Project panel keeps its buttons)
    if (menuact::BeginMenu("Build", hasProject_)) {
        const bool busy = runner_.busy();
        if (menuact::MenuItem("Build", "Ctrl+Shift+B", false, !busy))
            runner_.buildAndRun(projectForBuild(), false);
        if (menuact::MenuItem("Rebuild", nullptr, false, !busy))
            runner_.buildAndRun(projectForBuild(), false, true);
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Full rebuild: recreates the build container, then compiles "
                "the engine\n(VU1 microprograms included) and every game "
                "source from scratch.\nSlow on purpose - it is the way out "
                "when an incremental build\nmisbehaves. Clean also wipes "
                "bin\\ on this machine; Rebuild does not.");
        if (menuact::MenuItem("Build && Run in PCSX2", "F5", false, !busy))
            runner_.buildAndRun(projectForBuild(), true, false, project_.activeScene);
        if (menuact::MenuItem("Run in PCSX2 (no build)", "Ctrl+F5", false, !busy))
            runner_.runEmulatorOnly(project_, project_.activeScene);
        ImGui::Separator();
        const bool ps2Ready = !project_.ps2LinkIp.empty();
        if (menuact::MenuItem("Build && Run on PS2", "F6", false, !busy && ps2Ready))
            runner_.buildAndRunPs2(projectForBuild(), true, false, project_.activeScene);
        if (menuact::MenuItem("Run on PS2 (no build)", "Ctrl+F6", false, !busy && ps2Ready))
            runner_.buildAndRunPs2(projectForBuild(), false, false, project_.activeScene);
        if (!ps2Ready && ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip("Set 'PS2 (ps2link) IP' in Edit > Preferences first.");
        if (menuact::MenuItem("Stop on PS2", nullptr, false, !busy && ps2Ready))
            runner_.stopPs2(project_);
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip("Kills the file server and resets ps2link - the "
                              "console reboots back to its listening state.");
        if (menuact::MenuItem("Power Off PS2", nullptr, false, !busy && ps2Ready))
            runner_.powerOffPs2(project_);
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Switches the console off - ps2link's own poweroff command,\n"
                "the same shutdown its power button performs. Nothing on the\n"
                "network can switch it back on again.");
        ImGui::Separator();
        if (menuact::MenuItem("Live Link", nullptr,
                            project_.settings.liveLink)) {
            project_.settings.liveLink = !project_.settings.liveLink;
            commitChange();
        }
        if (menuact::MenuItem("Live Debugger", nullptr,
                            project_.settings.liveDebug)) {
            project_.settings.liveDebug = !project_.settings.liveDebug;
            commitChange();
        }
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Debug builds report every flow-graph node they run, and "
                "take breakpoint,\n"
                "pause/step and force-fire commands from "
                "the editor (docs/live-debugger.md).\n"
                "Open the panel with "
                "Tools > Debugger (F9) or the DBG chip in the toolbar.");
        if (menuact::MenuItem("Live Logic", nullptr,
                            project_.settings.liveLogic)) {
            project_.settings.liveLogic = !project_.settings.liveLogic;
            commitChange();
        }
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Edit a flow graph and the RUNNING game changes - no "
                "rebuild.\nThe editor compiles the graph itself and a debug "
                "build interprets it;\ngraphs the interpreter cannot "
                "express are named in the Debugger's Logic tab\n"
                "(docs/live-logic.md).");
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip(
                "Mirror scene edits (move/rotate/scale/recolor objects, "
                "add/delete them)\ninto the running game without a rebuild "
                "- PCSX2 and real-PS2 deploys alike.\nA project setting: "
                "off = the game is built without the poller and the "
                "editor\nnever writes snapshots. Needs the \"debug\" build "
                "profile (Project >\nPreferences > Build & debug). Also toggled by "
                "clicking the LIVE chip in the toolbar.");
        // The bakes, as the tabs that own them start them (startGiBake & co.
        // in hud_ui.cpp): listed here so the command palette finds every bake
        // by typing "bake". Disabled while that bake runs or is switched off.
        ImGui::Separator();
        {
            const ProjectSettings& bs = project_.settings;
            const std::string scn = project_.scenes.empty() ? std::string() : project_.active().name;
            if (menuact::MenuItem("Bake global illumination", nullptr, false,
                                  bs.giEnabled && !giBaker_.running()))
                startGiBake(false);
            menuact::Hint("Lighting \xc2\xb7 probes and lightmaps for scene " + scn);
            if (menuact::MenuItem("Bake global illumination for all scenes", nullptr, false,
                                  bs.giEnabled && !giBaker_.running()))
                startGiBake(true);
            menuact::Hint("Lighting \xc2\xb7 probes and lightmaps for every scene");
            if (menuact::MenuItem("Bake ambient occlusion", nullptr, false, !modelAoBaker_.running()))
                startModelAoBake();
            menuact::Hint("Lighting \xc2\xb7 model AO baked into each model's texture");
            const int prelitPending = litBaker_.running() ? 0 : prelitPendingCount();
            if (menuact::MenuItem("Bake pre-lit models", nullptr, false, prelitPending > 0))
                startPrelitBake(true);
            menuact::Hint("Lighting \xc2\xb7 " + std::to_string(prelitPending) + " pending in scene " + scn);
            if (menuact::MenuItem("Bake shadow decals", nullptr, false,
                                  bs.bakedShadows && !shadowBaker_.running()))
                startShadowBake(false);
            menuact::Hint("Lighting \xc2\xb7 projected shadows for scene " + scn);
            if (menuact::MenuItem("Bake shadow decals for all scenes", nullptr, false,
                                  bs.bakedShadows && !shadowBaker_.running()))
                startShadowBake(true);
            menuact::Hint("Lighting \xc2\xb7 projected shadows for every scene");
            if (menuact::MenuItem("Bake stale procedural volumes", nullptr, false,
                                  !busy && procbake::anyStale(project_))) {
                // What a build does first (projectForBuild), on its own.
                const procbake::Report rep = bakeStaleProcVolumes();
                statusMessage_ = rep.error.empty()
                                     ? "Baked " + std::to_string(rep.instances) + " procedural instances into " +
                                           std::to_string(rep.chunks) + " chunk meshes"
                                     : "Procedural bake failed: " + rep.error;
            }
            menuact::Hint("Build \xc2\xb7 chunk meshes for every out-of-date volume");
        }
        ImGui::Separator();
        if (menuact::MenuItem("Cancel Build", nullptr, false, busy)) runner_.cancel();
        if (menuact::MenuItem("Clean", nullptr, false, !busy))
            runner_.clean(project_);
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
            ImGui::SetTooltip("Deletes bin\\ and the container build cache "
                              "(obj) - the next build starts from scratch.");
        menuact::EndMenu();
    }

    if (menuact::BeginMenu("Session")) {
        const bool active = session_.active();
        if (menuact::MenuItem("Host Session...", nullptr, false,
                            hasProject_ && !active))
            openHostSessionPopup_ = true;
        if (menuact::MenuItem("Join Session...", nullptr, false, !active))
            requestJoinSession();
        ImGui::Separator();
        if (menuact::MenuItem("Session Window", nullptr, showSessionWindow_, active))
            showSessionWindow_ = !showSessionWindow_;
        if (menuact::MenuItem(session_.role() == session::Session::Role::Client
                                ? "Leave Session"
                                : "Close Session",
                            nullptr, false, active))
            closeSession();
        menuact::EndMenu();
    }

    // One flat list under labelled headers rather than submenus: every
    // doc page, tooltip and AI prompt in the repo names a tool as
    // "Tools > X", and a submenu would put a word into all of those
    // paths. Groups answer "what am I working on"; inside a group the
    // items are ALPHABETICAL, so a tool is found by reading, not by
    // remembering where it landed the day it was added.
    if (hasProject_ && menuact::BeginMenu("Tools")) {
        ImGui::SeparatorText("Assets");
        if (menuact::MenuItem("Animation Editor...")) showAnimEditor_ = true;
        if (menuact::MenuItem("Asset Browser...")) {
            showAssetBrowser_ = true;
            scanAssetTree();
        }
        if (menuact::MenuItem("Drone Generator...")) showDroneGenerator_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Ambient / drone music generator: audition a patch live,\n"
                "render it into res/audio as a looping background track.");
        if (menuact::MenuItem("Font Manager...")) showFontManager_ = true;
        if (menuact::MenuItem("Material Editor...")) showMaterialEditor_ = true;
        if (menuact::MenuItem("Particle Editor...")) showParticles_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip("The particle library: effects defined once, used by\n"
                              "emitters and vehicle tyre smoke.");
        if (menuact::MenuItem("Texture Atlas...")) {
            showTextureAtlas_ = true;
            atlasPlanDirty_ = true;
        }
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "What the build packed into shared texture pages, what it\n"
                "refused and why, and what it costs in GS VRAM - plus the\n"
                "per-texture keep-out and grouping controls. A page is ONE\n"
                "allocation and ONE palette, so what shares one is worth\n"
                "looking at.");
        if (menuact::MenuItem("Tree Generator...")) {
            showTreeGenerator_ = true;
            treePreviewDirty_ = true;
        }

        if (menuact::MenuItem("Vehicle Editor...")) showVehicles_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Driveable cars. Define one - model, wheels, how it drives -\n"
                "and place it in as many scenes as you like. The wheels are\n"
                "found in the model by their geometry, so their names in\n"
                "Blender do not matter.");

        ImGui::SeparatorText("Scene");
        if (menuact::MenuItem("Cutscene Director...")) showCutsceneEditor_ = true;
        if (menuact::MenuItem("Phone Camera...")) showPhoneCamWindow_ = true;
        if (menuact::MenuItem("Prefabs...")) showPrefabs_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Reusable groups of objects - a hut, a room, a lamp post\n"
                "with its light and its script. Stamp them by hand, scatter\n"
                "them with a procedural graph, or spawn them at runtime.");
        if (menuact::MenuItem("Procedural...")) showProcedural_ = true;
        if (menuact::MenuItem("Terrain Editor...")) showTerrainEditor_ = true;

        ImGui::SeparatorText("Lighting & rendering");
        if (menuact::MenuItem("Ambience Editor...")) showAmbienceEditor_ = true;
        if (menuact::MenuItem("Baked Lighting...")) {
            showAmbienceEditor_ = true;
            showBakedLighting_ = true;
        }
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Light baked on the host and shipped as pixels: automatic\n"
                "model AO multiplied into each model's own texture.");
        if (menuact::MenuItem("Color Grading...")) showGradingEditor_ = true;
        // The two bakes live in the Ambience Editor now; the menu items
        // still work and simply open that window on their tab.
        if (menuact::MenuItem("Global Illumination...")) {
            showAmbienceEditor_ = true;
            showGiBake_ = true;
        }
        if (menuact::MenuItem("Neural Upscaler (BLSS)...")) showBlss_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Train, cross-validate and inspect the reduced-resolution\n"
                "reconstruction network, and look at the pictures it makes.\n"
                "Everything --blss-train / --blss-eval / --blss-emit can do,\n"
                "without a terminal. Proof of concept - read the notes.");
        if (menuact::MenuItem("Static Batches...")) {
            showStaticBatches_ = true;
            batchDirty_ = true;
        }
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Which static objects merged into one submit, what each\n"
                "batch costs in VU1 packages against drawing its members\n"
                "solo, and WHY every object that is not batched is not.\n"
                "A batch is culled as a unit, so its merged box is worth\n"
                "looking at.");
        if (menuact::MenuItem("VU Programs...")) showVuPrograms_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Compose a VU1 microprogram out of stages - wobble, twist,\n"
                "posterize - and see the micro memory it costs, the VCL it\n"
                "generates and what it computes, without a console. Also\n"
                "VU0 compute kernels.");

        ImGui::SeparatorText("Screens & menus");
        if (menuact::MenuItem("Credits Editor...")) showCreditsEditor_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "End credits: headings, role/name pairs, images and page\n"
                "breaks, imported from a text file if you like, scrolling\n"
                "over music with a skip button and somewhere to go after.");
        if (menuact::MenuItem("Loading Screens...")) showLoadingEditor_ = true;
        if (menuact::MenuItem("Menu Editor...")) showMenusEditor_ = true;
        if (menuact::MenuItem("Menu Preview...")) showMenuPreview_ = true;
        if (menuact::MenuItem("UI Editor...")) showUiEditor_ = true;

        ImGui::SeparatorText("Gameplay");
        if (menuact::MenuItem("Input Map...")) showInputMap_ = true;
        if (menuact::MenuItem("Save Editor...")) showSaveEditor_ = true;
        if (menuact::MenuItem("World Facts...")) {
            // Focused, not just opened: docked as a background tab it would
            // look like nothing happened (drawWorldFactsWindow).
            showWorldFacts_ = true;
            factFocusFrames_ = 3;
        }
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "The game's central memory: named, typed facts like\n"
                "\"the generator is repaired\" or \"marta.trust\", the\n"
                "reusable conditions over them, the rules that react,\n"
                "and a live blackboard of every one of them while the\n"
                "game runs.");

        ImGui::SeparatorText("Running game");
        if (menuact::MenuItem("Debugger...", "F9")) showDebugger_ = true;
        if (menuact::MenuItem("Remote Pad...")) showRemotePad_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Hold the running game's controller from here - click the\n"
                "buttons or drive it with the editor's keyboard. PCSX2 does\n"
                "not need the focus, and the same channel is scriptable\n"
                "(tyrax-editor --pad). Debug builds only.");

        ImGui::SeparatorText("AI");
        if (menuact::MenuItem("AI Assistant...")) showAiChat_ = true;
        if (ImGui::IsItemHovered())
            ImGui::SetTooltip(
                "Ask about the editor - it answers from the editor's own\n"
                "documentation - or ask for something to be done: it can\n"
                "add and change objects, write flow graphs, switch scenes\n"
                "and open windows. Uses the AI backend from Edit >\n"
                "Preferences; every change it makes is one Ctrl+Z away.");
        menuact::EndMenu();
    }
    // Deliberately outside the project gate: which build this is, and
    // whether there is a newer one, are questions somebody has on the
    // welcome screen too (docs/updates.md).
    if (menuact::BeginMenu("Help")) {
        menuact::MenuItem(("TyraX " + std::string(version::kEditorVersion)).c_str(),
                        nullptr, false, false);
        // Trademark notice: the editor names the console it builds for and
        // draws its pad's buttons where they ARE buttons (Remote Pad, input
        // prompts) - say whose marks those are.
        ImGui::PushTextWrapPos(ImGui::GetCursorPosX() + scaled(300.0f));
        ImGui::TextDisabled("%s", "\"PlayStation\" and the PlayStation button symbols are trademarks of Sony Interactive Entertainment. TyraX is an independent project, not affiliated with or endorsed by Sony.");
        ImGui::PopTextWrapPos();
        ImGui::Separator();
        const bool updateBusy = updateChecking_ || updateDownloading_;
        if (menuact::MenuItem("Check for updates...", nullptr, false, !updateBusy))
            startUpdateCheck(true);
        if (!updateStatus_.empty()) ImGui::TextDisabled("%s", updateStatus_.c_str());
        ImGui::Separator();
        if (menuact::MenuItem("Documentation"))
            platform::openUrl(std::string("https://github.com/") +
                              update::kRepo + "/blob/main/docs/README.md");
        if (menuact::MenuItem("Releases"))
            platform::openUrl(std::string("https://github.com/") +
                              update::kRepo + "/releases");
        if (menuact::MenuItem("Report an issue"))
            platform::openUrl(std::string("https://github.com/") +
                              update::kRepo + "/issues");
        menuact::EndMenu();
    }
}

// Runs the toolbar's selected target (runOnPs2_). One place, so the Play
// button, its dropdown and anything else that grows later cannot disagree
// about what "Run" means.
// A game launched WITH the debugger opens the Debugger panel if it is closed.
// This is the whole of what the old Debug toolbar button did on top of Run, and
// having it as a separate button meant the ordinary Run silently started a debug
// session with nowhere to watch it: the game reported every node it fired and
// the editor put that on a panel nobody had opened. Two conditions, both already
// meaningful on their own - the debug build profile, and the Live Debugger
// project setting - so nothing pops up in a release build or for anyone who
// turned the debugger off.
//
// Opening is not enough since the Debugger became a tab of the console drawer
// (Output / Debug / Debugger share the Default layout's bottom node): an open
// but unselected tab is as invisible as a closed panel. So a debug launch also
// brings the tab forward (pendingFocusWindow_, settled once the window has been
// submitted). Never the reverse: a panel the user closed mid-session stays
// closed until the next launch, and nothing re-docks it. Build progress stays
// reachable through the status bar's BUILDING / BUILD FAILED chip, which
// brings Output forward.
void App::openDebuggerForLaunch() {
    if (project_.settings.buildProfile == "debug" && project_.settings.liveDebug) {
        showDebugger_ = true;
        pendingFocusWindow_ = "Debugger";
    }
}

void App::runSelectedTarget(bool build) {
    openDebuggerForLaunch();
    if (runOnPs2_) runner_.buildAndRunPs2(projectForBuild(), build, false, project_.activeScene);
    else if (build) runner_.buildAndRun(projectForBuild(), true, false, project_.activeScene);
    else runner_.runEmulatorOnly(project_, project_.activeScene);
}

// Baked shadow decals (docs/shadows.md): push the CACHED bake into the
// viewport. The editor never bakes here - a bake is pressed, not implied - so
// this is a cache read keyed on what could have invalidated it: the active
// scene, the model's edit serial (which moves when a caster or a receiver
// does, staling the signature), the project switch, and the baker's own
// version so a finished bake appears without anyone touching the scene.
void App::updateShadowDecals() {
    uint64_t key = 1469598103934665603ull;
    const auto mix = [&](uint64_t v) { key = (key ^ v) * 1099511628211ull; };
    mix((uint64_t)project_.activeScene);
    mix(modelEditSerial_);
    mix(project_.settings.bakedShadows ? 1u : 0u);
    mix(shadowBaker_.version());
    mix(project_.settings.bakedShadowAutoBake ? 1u : 0u);
    if (key == shadowPreviewKey_) return;
    shadowPreviewKey_ = key;

    Viewport::ShadowPreview pv;
    pv.version = ++shadowPreviewVersion_;
    // With the background re-bake on, the last bake stays on screen until the
    // new one lands - a moved caster's shadow trails it for a few seconds
    // instead of every shadow in the scene blinking out. Without it, a stale
    // bake shows nothing, exactly as the game would get nothing.
    const shadowbake::Bake b =
        project_.settings.bakedShadowAutoBake
            ? shadowbake::loadAny(project_, project_.activeScene)
            : shadowbake::load(project_, project_.activeScene);
    if (b.valid && (!b.groups.empty() || !b.ground.empty())) {
        pv.pageSize = shadowbake::kPageSize;
        // The pages as the console samples them: the bake's own tint in RGB,
        // its alpha in A. Expanded here rather than stored that way, for the
        // reason the cache stores one byte a texel - the tint is one colour
        // per scene, not per pixel.
        for (const shadowbake::Page& pg : b.pages) {
            std::vector<unsigned char> rgba((size_t)pv.pageSize * pv.pageSize * 4, 0);
            for (size_t i = 0; i < pg.alpha.size() && i * 4 + 3 < rgba.size(); ++i) {
                rgba[i * 4 + 0] = b.tint[0];
                rgba[i * 4 + 1] = b.tint[1];
                rgba[i * 4 + 2] = b.tint[2];
                rgba[i * 4 + 3] = pg.alpha[i];
            }
            pv.pages.push_back(std::move(rgba));
        }
        for (const shadowbake::Group& g : b.groups) {
            Viewport::ShadowPreview::Draw d;
            d.verts = g.verts;
            d.page = g.page;
            pv.draws.push_back(std::move(d));
        }
        // Ground shadow maps (docs/shadows.md, "Ground shadow maps"): packed
        // into extra preview pages and drawn over the cells the game draws
        // them on - the same cell masks, the same chunk-square STs and the
        // same quad diagonal, lifted a little more than the game's 0.02 for
        // the GL depth buffer.
        const SceneData& sc = project_.scenes[project_.activeScene];
        const int res = b.groundRes;
        if (!b.ground.empty() && res > 0 && res <= pv.pageSize && sc.hmW >= 2 &&
            sc.hmD >= 2 && (int)sc.heights.size() == sc.hmW * sc.hmD) {
            const int C = shadowbake::kGroundChunkCells;
            const int per = pv.pageSize / res;
            const int cellsX = sc.hmW - 1, cellsZ = sc.hmD - 1;
            const float W = (float)sc.terrain.width, D = (float)sc.terrain.depth;
            const float stepX = W / (float)cellsX, stepZ = D / (float)cellsZ;
            const float lift = 0.05f;
            const auto hAt = [&](int ix, int iz) {
                return sc.heights[(size_t)iz * sc.hmW + ix] + lift;
            };
            int slot = 0, page = -1;
            for (const shadowbake::GroundMap& gm : b.ground) {
                if ((int)gm.alpha.size() != res * res) continue;
                if (slot % (per * per) == 0) {
                    pv.pages.emplace_back((size_t)pv.pageSize * pv.pageSize * 4, 0);
                    page = (int)pv.pages.size() - 1;
                }
                const int sl = slot++ % (per * per);
                const int ox = (sl % per) * res, oy = (sl / per) * res;
                std::vector<unsigned char>& px = pv.pages[(size_t)page];
                for (int y = 0; y < res; ++y)
                    for (int x = 0; x < res; ++x) {
                        unsigned char* t =
                            &px[((size_t)(oy + y) * pv.pageSize + ox + x) * 4];
                        t[0] = b.tint[0], t[1] = b.tint[1], t[2] = b.tint[2];
                        t[3] = gm.alpha[(size_t)y * res + x];
                    }
                // Half a texel in from the slot's edge: the filter must not
                // reach the neighbouring slot.
                const float ps = (float)pv.pageSize;
                const float u0 = (ox + 0.5f) / ps, v0 = (oy + 0.5f) / ps;
                const float du = (res - 1.0f) / ps, dv = (res - 1.0f) / ps;
                const std::vector<uint16_t> rows = shadowbake::groundCellMask(gm, res);
                const int gx0 = gm.cx * C, gz0 = gm.cz * C;
                Viewport::ShadowPreview::Draw d;
                d.page = page;
                for (int r = 0; r < C && gz0 + r < cellsZ; ++r)
                    for (int c = 0; c < C && gx0 + c < cellsX; ++c) {
                        if (!(rows[r] & (1u << c))) continue;
                        const int x = gx0 + c, z = gz0 + r;
                        const float x0 = -W * 0.5f + x * stepX, x1 = x0 + stepX;
                        const float z0 = -D * 0.5f + z * stepZ, z1 = z0 + stepZ;
                        const float u_0 = u0 + du * (float)c / C, u_1 = u0 + du * (float)(c + 1) / C;
                        const float v_0 = v0 + dv * (float)r / C, v_1 = v0 + dv * (float)(r + 1) / C;
                        const float q[6][5] = {
                            {x0, hAt(x, z), z0, u_0, v_0},
                            {x1, hAt(x + 1, z), z0, u_1, v_0},
                            {x0, hAt(x, z + 1), z1, u_0, v_1},
                            {x1, hAt(x + 1, z), z0, u_1, v_0},
                            {x1, hAt(x + 1, z + 1), z1, u_1, v_1},
                            {x0, hAt(x, z + 1), z1, u_0, v_1}};
                        for (const auto& v : q) d.verts.insert(d.verts.end(), v, v + 5);
                    }
                if (!d.verts.empty()) pv.draws.push_back(std::move(d));
            }
        }
    }
    viewport_.setShadowDecals(pv);
}

// Drains shadowBaker_. Unlike the GI and pre-lit polls there is nothing to
// apply back onto the model - the bake lives entirely on disk - so this only
// has to make the finished result visible. Called every frame from drawUI and
// from nowhere else (the giBakerPoll rule): a bake started from the Ambience
// Editor has to land whether or not that tab is still open when it ends.
void App::shadowBakerPoll() {
    if (!hasProject_) return;
    // Re-baked while you edit (docs/shadows.md): any edit makes the WHOLE
    // scene's cache stale - the signature covers every caster and receiver -
    // and a stale cache draws nothing, so one moved crate used to take every
    // shadow in the scene with it until someone pressed Bake. With the
    // auto-bake switch on, wait for the edits to settle (a gizmo drag is many
    // edits), then re-bake the active scene in the background. The other
    // scenes are left to the build's pre-bake.
    {
        const ProjectSettings& st = project_.settings;
        const bool autoOn = st.bakedShadows && st.bakedShadowAutoBake;
        const uint64_t key = modelEditSerial_ * 31u + (uint64_t)project_.activeScene;
        if (!shadowBaker_.running()) shadowAutoRunning_ = false;
        if (key != shadowAutoKey_) {
            shadowAutoKey_ = key;
            shadowAutoEditTime_ = ImGui::GetTime();
            shadowAutoPending_ = autoOn;
            // Baking a scene the next edit already invalidated is wasted time.
            if (shadowAutoRunning_) {
                shadowBaker_.cancel();
                shadowAutoRunning_ = false;
            }
        }
        if (autoOn && shadowAutoPending_ && !shadowBaker_.running() &&
            ImGui::GetTime() - shadowAutoEditTime_ > 1.0) {
            shadowAutoPending_ = false;
            if (!shadowbake::isFresh(project_, project_.activeScene)) {
                shadowBaker_.start(project_, {project_.activeScene});
                shadowAutoRunning_ = true;
            }
        }
    }
    const uint64_t v = shadowBaker_.version();
    if (v == shadowBakeVersion_) return;
    shadowBakeVersion_ = v;
    // updateShadowDecals folds the baker's version into its own key, so the
    // next frame re-reads the cache on its own. What it cannot see is the
    // terrain mesh and the GI textures the viewport holds, which a bake does
    // not touch - hence no applyProjectToViewport here.
    shadowPreviewKey_ = 0;
}

void App::updateProjectedDecals() {
    // Cheap signature of everything a projection depends on: the projecting
    // decals AND every potential receiver's transform/type. Recompute only when
    // it changes (edits, gizmo drags), so the projection - which walks receiver
    // geometry - doesn't run every frame. Pure host work; nothing here reaches
    // the PS2 (see decalproj).
    const SceneData& sc = project_.active();
    bool anyProjecting = false;
    for (const SceneObject& o : sc.objects)
        if (o.type == PrimitiveType::Decal && o.decalProject) { anyProjecting = true; break; }

    uint64_t sig = 1469598103934665603ull;  // FNV-1a seed
    auto mix = [&](uint64_t v) { sig = (sig ^ v) * 1099511628211ull; };
    auto mixf = [&](float f) {
        uint32_t b;
        std::memcpy(&b, &f, sizeof(b));
        mix(b);
    };
    if (anyProjecting) {
        mix(sc.objects.size());
        for (const SceneObject& o : sc.objects) {
            mix((uint64_t)o.type);
            for (int k = 0; k < 3; ++k) { mixf(o.position[k]); mixf(o.rotation[k]); mixf(o.scale[k]); }
            mix((uint64_t)o.primDetail);
            mix(o.primRings ? 1u : 0u);
            for (char c : o.id) mix((uint8_t)c);
            for (char c : o.modelPath) mix((uint8_t)c);
            if (o.type == PrimitiveType::Decal) {
                mix(o.decalProject ? 2u : 1u);
                for (char c : o.materialPath) mix((uint8_t)c);
            }
        }
        for (float h : sc.heights) mixf(h);  // terrain receiver
        mix(sc.terrain.enabled ? 1u : 0u);   // ...which a removed terrain isn't
    }

    if (sig == projectedDecalsSig_) {
        viewport_.setProjectedDecals(projectedDecals_, projectedDecalsVersion_);
        return;
    }
    projectedDecalsSig_ = sig;
    projectedDecals_.clear();
    if (anyProjecting) {
        for (const SceneObject& o : sc.objects) {
            if (o.type != PrimitiveType::Decal || !o.decalProject || o.materialPath.empty())
                continue;
            decalproj::DecalMesh m = decalproj::project(project_, sc, o);
            if (!m.verts.empty()) projectedDecals_[o.id] = std::move(m.verts);
        }
    }
    ++projectedDecalsVersion_;
    viewport_.setProjectedDecals(projectedDecals_, projectedDecalsVersion_);
}

// Terrain brush ranges scale with the map: a 64-unit garden and a 2000-unit
// world need very different maximums (fixed 30/0.5 caps made the brush useless
// on large maps). Sliders over these ranges are logarithmic, so small values
// keep their precision on any map size.
static float terrainDimOf(const Project& p) {
    const TerrainConfig& t = p.active().terrain;
    return (float)(t.width > t.depth ? t.width : t.depth);
}
static float brushMaxRadius(const Project& p) {
    const float r = terrainDimOf(p) * 0.5f;  // up to half the map per stroke
    return r > 30.0f ? r : 30.0f;
}
static float sculptMaxStrength(const Project& p) {
    const float s = terrainDimOf(p) / 100.0f;  // big maps = big landforms
    return s > 0.5f ? s : 0.5f;
}

void App::updateNavOverlay() {
    // Nav-mesh preview (View > Nav Mesh Overlay). Signature of everything the
    // bake depends on - blocking objects, terrain, the nav preferences - so
    // navmesh::bake only reruns on actual edits (same trick as the projected
    // decals). Pure host work; the game bakes its own copy at build time.
    if (!showNavOverlay_) {
        viewport_.setNavOverlay(nullptr, 0);
        return;
    }
    const SceneData& sc = project_.active();
    uint64_t sig = 1469598103934665603ull;  // FNV-1a seed
    auto mix = [&](uint64_t v) { sig = (sig ^ v) * 1099511628211ull; };
    auto mixf = [&](float f) {
        uint32_t b;
        std::memcpy(&b, &f, sizeof(b));
        mix(b);
    };
    mixf(project_.settings.navCellSize);
    mixf(project_.settings.navMaxSlope);
    mixf(project_.settings.navAgentRadius);
    mix((uint64_t)sc.terrain.width);
    mix((uint64_t)sc.terrain.depth);
    mix(sc.terrain.enabled ? 1u : 0u);  // no terrain = nothing walkable at all
    mix(sc.objects.size());
    for (const SceneObject& o : sc.objects) {
        mix((uint64_t)o.type);
        mix((uint64_t)o.collisionMode);
        for (int k = 0; k < 3; ++k) { mixf(o.position[k]); mixf(o.scale[k]); }
        for (char c : o.modelPath) mix((uint8_t)c);
    }
    for (const auto& [asset, b] : project_.modelCollision) {  // models' own boxes
        for (char c : asset) mix((uint8_t)c);
        for (int k = 0; k < 3; ++k) { mixf(b.mn[k]); mixf(b.mx[k]); }
    }
    for (float h : sc.heights) mixf(h);

    if (sig != navOverlaySig_) {
        navOverlaySig_ = sig;
        navGrid_ = navmesh::bake(project_, sc);
        ++navOverlayVersion_;
    }
    viewport_.setNavOverlay(&navGrid_, navOverlayVersion_);
}

// Fit a path into maxW pixels by dropping characters from the FRONT: the tail
// (the project's own folder) is what identifies it, the drive root is not.
// Binary search over the cut - the fit is monotonic, and this runs per row
// per frame.
static std::string ellipsizePathLeft(const std::string& s, float maxW) {
    if (ImGui::CalcTextSize(s.c_str()).x <= maxW) return s;
    size_t lo = 0, hi = s.size();  // smallest cut that fits
    while (lo < hi) {
        const size_t mid = (lo + hi) / 2;
        if (ImGui::CalcTextSize(("..." + s.substr(mid)).c_str()).x <= maxW)
            hi = mid;
        else
            lo = mid + 1;
    }
    // Never cut inside a UTF-8 sequence - a path can carry accented folder
    // names, and half a codepoint draws as garbage.
    while (lo < s.size() && ((unsigned char)s[lo] & 0xC0) == 0x80) ++lo;
    return "..." + s.substr(lo);
}

